/* === Tab panels =============================================== */
/* Tabular nav: only the active panel visible (matches tab pill breakpoint). */
@media (max-width: 1023.98px) {
  [data-tab-panel] { display: none; }
  body.active-tab-newsfeed [data-tab-panel="newsfeed"],
