  max-height: 75vh;
  overflow: hidden;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
  animation: search-card-in 0.12s ease-out;
}

/* New multi-select picker head + selected row + footer */
.wiz-topic-overlay-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.85rem 1.15rem;
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}
.wiz-topic-overlay-label {
  font-family: var(--font-display);
  font-weight: var(--font-weight-bold);
  color: var(--color-primary);
  font-size: 1rem;
  letter-spacing: -0.01em;
}
.wiz-topic-overlay-selected {
  padding: 0.75rem 1.15rem;
  border-bottom: 1px solid var(--color-border);
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  flex-shrink: 0;
  max-height: 120px;
  overflow-y: auto;
}
.wiz-topic-overlay-empty {
  color: var(--color-text-light);
  font-size: 0.82rem;
}
.wiz-topic-overlay-sel {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.2rem 0.35rem 0.2rem 0.55rem;
  background: #4a6a8a;
  color: white;
  border-radius: 3px;
  font-size: 0.78rem;
  font-weight: var(--font-weight-medium);
  max-width: 100%;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
}
.wiz-topic-overlay-sel-remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  background: rgba(255, 255, 255, 0.2);
  color: white;
  border: none;
  border-radius: 50%;
  cursor: pointer;
  font-size: 0.82rem;
  line-height: 1;
}
@media (hover: hover) { .wiz-topic-overlay-sel-remove:hover { background: rgba(255, 255, 255, 0.35); } }

.wiz-topic-overlay-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1.15rem;
  border-top: 1px solid var(--color-border);
  flex-shrink: 0;
  background: var(--color-bg-light, #f6f7f9);
}
.wiz-topic-overlay-count {
  color: var(--color-text-muted);
  font-size: 0.82rem;
  font-weight: var(--font-weight-medium);
}
.wiz-topic-overlay-done {
  padding: 0.5rem 1.25rem;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 4px;
  font-weight: var(--font-weight-semibold);
  font-size: 0.88rem;
  cursor: pointer;
  transition: background 0.15s;
}
@media (hover: hover) { .wiz-topic-overlay-done:hover {
  background: var(--color-primary-dark, var(--color-primary));
} }

.wiz-topic-overlay-check {
  margin-left: auto;
  color: var(--color-primary);
  font-weight: var(--font-weight-bold);
}
.wiz-topic-overlay-result.is-selected {
  background: var(--color-accent);
  color: var(--color-primary);
}
.wiz-topic-overlay-chip.is-selected {
  background: var(--color-primary);
  color: white;
  border-color: var(--color-primary);
}

.wiz-topic-overlay-input-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 1.15rem;
  border-bottom: 1px solid var(--color-border);
  flex-shrink: 0;
}

.wiz-topic-overlay-icon {
  font-size: 1.15rem;
  color: var(--color-primary);
  flex-shrink: 0;
}

.wiz-topic-overlay-input {
  flex: 1;
  border: none;
  outline: none;
  font-size: 1.05rem;
  font-family: var(--font-family);
  color: var(--color-text);
  font-weight: var(--font-weight-medium);
  background: transparent;
  min-width: 0;
}

.wiz-topic-overlay-close {
  background: none;
  border: none;
  font-size: 1.1rem;
  color: var(--color-text-muted);
  cursor: pointer;
  padding: 0.25rem 0.5rem;
}

@media (hover: hover) { .wiz-topic-overlay-close:hover {
  color: var(--color-text);
} }

.wiz-topic-overlay-body {
  flex: 1;
  overflow-y: auto;
  padding: 1rem 1.15rem 1.15rem;
}

.wiz-topic-overlay-group {
  margin-bottom: 1rem;
}

.wiz-topic-overlay-group:last-child {
  margin-bottom: 0;
}

.wiz-topic-overlay-group-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  color: var(--color-primary);
  font-weight: var(--font-weight-bold);
  letter-spacing: 0.08em;
  margin-bottom: 0.45rem;
}

.wiz-topic-overlay-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}

.wiz-topic-overlay-chip {
  padding: 0.32rem 0.75rem;
  background: var(--color-bg-light);
  border: 1px solid var(--color-border);
  border-radius: 999px;
  font-size: 0.82rem;
  font-family: var(--font-family);
  cursor: pointer;
  color: var(--color-text);
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

@media (hover: hover) { .wiz-topic-overlay-chip:hover {
  background: var(--color-primary);
  color: white;
  border-color: var(--color-primary);
} }

.wiz-topic-overlay-chip-parent {
  font-weight: var(--font-weight-semibold);
  background: white;
  border-color: var(--color-primary-light);
  color: var(--color-primary);
}

.wiz-topic-overlay-result {
  padding: 0.6rem 0.85rem;
  border-radius: 6px;
  cursor: pointer;
  font-size: 0.92rem;
  color: var(--color-text);
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.wiz-topic-overlay-result.highlighted {
  background: var(--color-accent);
}
@media (hover: hover) { .wiz-topic-overlay-result:hover {
  background: var(--color-accent);
} }

.wiz-topic-overlay-result-custom {
  background: var(--color-accent);
  margin-bottom: 0.5rem;
}

.wiz-topic-overlay-badge {
  background: var(--color-primary);
  color: white;
  font-size: 0.7rem;
  padding: 2px 7px;
  border-radius: 4px;
  font-weight: var(--font-weight-bold);
  flex-shrink: 0;
}

.wiz-topic-overlay-section-label {
  font-size: 0.7rem;
  text-transform: uppercase;
  color: var(--color-text-muted);
  font-weight: var(--font-weight-semibold);
  letter-spacing: 0.06em;
  margin: 0.6rem 0 0.4rem;
}

.wiz-topic-overlay-result-parent {
  color: var(--color-text-light);
  font-size: 0.78rem;
  margin-left: 0.4rem;
}

@media (max-width: 640px) {
  .wiz-topic-overlay {
    padding: 0;
    align-items: stretch;
  }
  .wiz-topic-overlay-card {
    max-width: none;
    height: 100vh;
    max-height: 100vh;
    border-radius: 0;
  }
}

/* === Knowledge Prompt Generator — Wizard Mode === */
/* Single-column prompt builder with bottom action bar */
.wiz-two-panel {
  display: flex;
  flex-direction: column;
  max-width: 100%;
}
.wiz-fields {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}
.wiz-intro {
  margin: 0 0 1rem;
  padding-bottom: 0;
  border-bottom: none;
}
.wiz-intro-text {
  font-size: 0.92rem;
  color: var(--color-text-muted);
  font-weight: 500;
  line-height: 1.5;
  margin: 0;
  max-width: 920px;
  letter-spacing: -0.005em;
}
@media (max-width: 640px) {
  .wiz-intro { margin-bottom: 0.85rem; }
  .wiz-intro-text { font-size: 0.88rem; line-height: 1.45; }
}

/* === Prompt Builder card grid + modal ============================
   Each .pb-card is one of the picker groups (Topics, Output,
   Sources & Citations, Scope, Custom). Clicking opens .pb-modal
   with the relevant pickers inside. */
/* Build a Custom Prompt = the SAME accordion language as the topic-page AI
   Insights list (revamp719): one clipped bordered container, borderless rows
   separated by hairlines, each row a numbered step — number → icon → title +
   subtext → chevron. */
.pb-card-grid {
  display: flex; flex-direction: column;
  border: 1px solid var(--color-surface-border); border-radius: 14px;
  background: #fff; overflow: hidden;
}
.pb-card {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  column-gap: 12px; row-gap: 0;
  width: 100%;
  padding: 15px 16px;
  background: none;
  border: none;
  border-bottom: 1px solid #eef1f6;
  border-radius: 0;
  text-align: left;
  cursor: pointer;
  font-family: inherit;
  color: inherit;
  box-shadow: none;
  transition: background .12s ease;
}
.pb-card:last-child { border-bottom: none; }
@media (hover: hover) { .pb-card:hover { background: #f7f9fc; } }
.pb-card.is-expanded { background: #f4f7fc; }
@media (hover: hover) { .pb-card.is-expanded:hover { background: #f4f7fc; } }
/* Step number — the build order, stated. */
.pb-card-num {
  display: inline-flex; align-items: center; justify-content: center;
  width: 22px; height: 22px; flex: none; margin-top: 1px;
  border-radius: 999px; background: #eaeff8; color: #4a5c7d;
  font-family: var(--font-family); font-size: 0.74rem; font-weight: 700; line-height: 1;
  transition: background .12s ease, color .12s ease;
}
.pb-card.is-expanded .pb-card-num,
.pb-card.has-items .pb-card-num { background: #2f4d9e; color: #fff; }
.pb-card-tx { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pb-card-titlerow { display: flex; align-items: center; gap: 8px; min-width: 0; flex-wrap: wrap; }
.pb-card-title {
  font-family: var(--font-display);
  font-size: 0.98rem;
  font-weight: 700;
  letter-spacing: -0.012em;
  color: #26375a;
  line-height: 1.25;
  flex: 0 1 auto;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pb-card-req {
  display: inline-flex;
  align-items: center;
  flex: none;
  padding: 0.22rem 0.5rem;
  background: color-mix(in srgb, var(--color-primary) 8%, #fff);
  color: var(--color-primary);
  border: 1px solid color-mix(in srgb, var(--color-primary) 16%, transparent);
  border-radius: 999px;
  font-family: var(--font-family);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  line-height: 1;
}
/* The expanded picker spans the full row width, under the text column. */
.pb-card-config { grid-column: 1 / -1; }
@media (max-width: 560px) {
  .pb-card { padding: 13px 13px; column-gap: 10px; }
  .pb-card-num { width: 20px; height: 20px; font-size: 0.7rem; }
  .pb-card-title { font-size: 0.92rem; }
}
/* Trailing action chip on every card — replaces the old chevron +
   separate "+ Add" CTA. Reads "Add +" when empty (clear call to
   action) or "Edit" when the card already has selections. Pill
   styling so it's visually obvious it's tappable. */
.pb-card-chev {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  margin-top: 1px;
  color: #a8b4c9;
  transition: transform 0.16s ease, color 0.14s;
}
.pb-card-chev svg { width: 18px; height: 18px; display: block; }
@media (hover: hover) { .pb-card:hover .pb-card-chev { color: #2c4467; } }
.pb-card.is-expanded .pb-card-chev { transform: rotate(180deg); color: #2c4467; }

/* Subtext sits in the row's text column, directly under the title. */
.pb-card-desc {
  display: block;
  font-family: var(--font-family);
  font-size: 0.8rem;
  color: var(--color-text-muted);
  font-weight: 500;
  line-height: 1.35;
  margin: 0;
}
/* The card's current selections, under the subtext. */
.pb-card-summary {
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: flex-start;
  padding-left: 0;
  margin-top: 0.4rem;
}
/* Labelled summary rows: "Primary topic(s): Banking" etc. (#img428/429). */
.pb-card-sumrow { font-family: var(--font-family); font-size: 0.83rem; line-height: 1.45; color: #1e2d44; }
.pb-card-sumlabel { font-weight: 700; color: #64748b; }
.pb-card-sumvals, .pb-card-sumtext { color: #1e2d44; }
.pb-card-sumrow--list { display: block; }
.pb-card-sumlist { margin: 3px 0 0; padding-left: 1.15rem; list-style: disc; }
.pb-card-sumlist li { color: #1e2d44; margin: 1px 0; }
.pb-card-sum-more { color: #2563eb; font-weight: 600; cursor: pointer; white-space: nowrap; }
@media (hover: hover) { .pb-card-sum-more:hover { text-decoration: underline; } }
.pb-card-chip {
  display: inline-flex;
  align-items: center;
  padding: 0.22rem 0.55rem;
  background: rgba(44, 68, 103, 0.07);
  color: #2c4467;
  border-radius: 999px;
  font-family: var(--font-family);
  font-size: 0.78rem;
  font-weight: 600;
  white-space: nowrap;
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
}
.pb-card-more {
  color: var(--color-text-muted);
  font-size: 0.78rem;
  font-weight: 500;
}

/* Modal overlay shared with the existing prompt-modal pattern. */
.pb-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
  animation: pb-modal-fade 0.16s ease-out;
}
@keyframes pb-modal-fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
.pb-modal-card {
  width: 100%;
  max-width: 640px;
  max-height: 88vh;
  background: var(--color-surface);
  border-radius: 16px;
  box-shadow: 0 24px 64px rgba(15, 26, 46, 0.28);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: pb-modal-rise 0.18s ease-out;
}
@keyframes pb-modal-rise {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}
.pb-modal-head {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.95rem 1.15rem 0.9rem;
  border-bottom: 1px solid var(--color-surface-border);
  flex-shrink: 0;
}
.pb-modal-close {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg-light, #f3f5f9);
  border: 1px solid #e6e8ec;
  border-radius: 9px;
  cursor: pointer;
  flex-shrink: 0;
  color: var(--color-text-muted);
  padding: 0;
  transition: background 0.14s, border-color 0.14s, color 0.14s, transform 0.06s;
}
@media (hover: hover) { .pb-modal-close:hover {
  background: #eef2f7;
  border-color: #c8d3e3;
  color: var(--color-text);
} }
.pb-modal-close:active { transform: translateY(1px); }
.pb-modal-title-block {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  min-width: 0;
  flex: 1;
}
.pb-modal-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 1.15rem;
  font-weight: 700;
  color: #1e2d44;
  letter-spacing: -0.018em;
}
.pb-modal-subtitle {
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.35;
  color: var(--color-text-muted);
  font-weight: 500;
}
.pb-modal-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 1rem 1.15rem;
}
.pb-modal-section + .pb-modal-section {
  /* Even spacing around every section divider: 18px above, 15px below (the ~3px
     less compensates the title's line-leading so the gap reads equal top+bottom)
     (#img376-380). Standardised with .pb-card-config + .pb-card-config-foot. */
  margin-top: 1.15rem;
  padding-top: 0.95rem;
  border-top: 1px solid #eef0f4;
}
.pb-modal-section-title {
  margin: 0 0 0.2rem;
  font-family: var(--font-display);
  /* Scaled down from 0.95rem/700 — the subsection headers read too heavy (#img347/#img355). */
  font-size: 0.84rem;
  font-weight: 600;
  line-height: 1.2; /* tighter leading so the header sits evenly below its divider */
  color: #1e2d44;
  letter-spacing: -0.01em;
}
.pb-modal-section-desc {
  margin: 0 0 0.6rem;
  font-size: 0.8rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}
.pb-modal-desc {
  margin: 0 0 0.75rem;
  font-size: 0.88rem;
  color: var(--color-text);
  line-height: 1.5;
}
.pb-modal-textarea {
  width: 100%;
  min-height: 150px;
  padding: 0.8rem 0.95rem;
  background: #f5f6f9;
  border: 1px solid #e1e6ee;
  border-radius: 10px;
  font-family: var(--font-family);
  /* Smaller resting text (#img362/363); bumps to 16px on focus so iOS doesn't zoom. */
  font-size: 0.9rem;
  color: var(--color-text);
  resize: vertical;
  line-height: 1.5;
  transition: background 0.14s, border-color 0.14s;
}
.pb-modal-textarea:focus {
  outline: none;
  background: var(--color-bg);
  border-color: #95a8c5;
  box-shadow: 0 0 0 3px rgba(74, 124, 201, 0.22);
  font-size: 16px; /* iOS zoom floor only while focused */
}
/* Accordion-card topic picker (opened from "Browse topics" inside
   the Topics buffer modal). Matches the site's Topics modal:
   parent cards with icon + name + chevron, expand to subtopic
   list. Supports multi-select via tick marks; Done returns the
   set. */
.pb-acc-search {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.65rem 0.85rem;
  background: #f4f5f7;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  margin-bottom: 0.85rem;
}
.pb-acc-search svg { color: var(--color-text-muted); flex-shrink: 0; }
.pb-acc-search-input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  /* iOS Safari auto-zooms into any input with font-size < 16px on
     focus — that's where the "zoom issue still occurring in prompt
     builder" was coming from. Bumped to 16px so the page no longer
     jumps when the user taps the search input. */
  font: 500 16px/1.2 var(--font-family);
  color: var(--color-text);
  min-width: 0;
  -webkit-appearance: none; appearance: none;
}
.pb-acc-search-input::placeholder { color: var(--color-text-light); font-weight: 500; }
.pb-acc-selected {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  padding: 0.6rem 0.7rem;
  background: rgba(44, 68, 103, 0.04);
  border: 1px dashed rgba(44, 68, 103, 0.2);
  border-radius: 10px;
  margin-bottom: 0.85rem;
}
.pb-acc-selchip {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.22rem 0.4rem 0.22rem 0.6rem;
  background: rgba(44, 68, 103, 0.1);
  color: #1e2d44;
  border-radius: 999px;
  font: 600 0.82rem/1 var(--font-family);
}
.pb-acc-selchip-x {
  width: 17px; height: 17px;
  border-radius: 999px;
  border: none;
  background: rgba(15, 26, 46, 0.1);
  color: var(--color-text-muted);
  font-size: 0.9rem;
  line-height: 1;
  cursor: pointer;
  padding: 0;
  display: inline-flex; align-items: center; justify-content: center;
}
@media (hover: hover) { .pb-acc-selchip-x:hover { background: rgba(15, 26, 46, 0.18); color: var(--color-text); } }

.pb-acc-list { display: flex; flex-direction: column; gap: 0.45rem; }
.pb-acc-card {
  background: var(--color-bg);
  border: 1px solid #e6e8ec;
  border-radius: 10px;
  overflow: hidden;
  transition: border-color 0.14s, box-shadow 0.14s;
}
.pb-acc-card.is-selected { border-color: #95a8c5; box-shadow: 0 1px 2px rgba(15, 26, 46, 0.04); }
.pb-acc-card.is-open { border-color: #c8d3e3; }
/* Entire head row is the expand toggle — single tap target. No more
   parent-auto-select on tap. The parent topic itself becomes a row
   inside the expanded body. */
.pb-acc-head {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  width: 100%;
  padding: 0.6rem 0.7rem;
  background: transparent;
  border: none;
  border-radius: 0;
  text-align: left;
  cursor: pointer;
  font: 600 0.95rem/1.2 var(--font-display);
  color: #1e2d44;
  letter-spacing: -0.008em;
  -webkit-tap-highlight-color: transparent;
  transition: background 0.12s;
}
@media (hover: hover) { .pb-acc-head:hover { background: rgba(15, 26, 46, 0.03); } }
.pb-acc-icon {
  display: inline-flex; align-items: center; justify-content: center;
  width: 28px; height: 28px;
  flex-shrink: 0;
  color: #2c4467;
}
.pb-acc-icon svg { width: 20px; height: 20px; display: block; }
.pb-acc-name { flex: 1; min-width: 0; }
.pb-acc-tick {
  display: inline-flex; align-items: center; justify-content: center;
  width: 18px; height: 18px;
  border-radius: 999px;
  background: rgba(44, 68, 103, 0.12);
  color: #2c4467;
  font-weight: 700;
  font-size: 0.78rem;
  flex-shrink: 0;
}
.pb-acc-chev {
  width: 26px; height: 26px;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--color-text-muted);
  flex-shrink: 0;
