/* Action bar — fixed at bottom of viewport on prompt generator */
.wiz-action-bar {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 90;
  background: var(--color-bg);
  border-top: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  gap: 1rem;
