  justify-content: center;
  gap: 0.45rem;
  min-height: 40px;
  padding: 0.6rem 1.1rem;
  border: 1px solid #d6dce6;
  border-radius: 10px;
  background: #fff;
  color: #33517f;
  font-family: var(--font-family);
  font-size: 0.88rem;
  font-weight: 650;
  cursor: pointer;
  white-space: nowrap;
  transition: background .14s, border-color .14s, color .14s;
}
@media (hover: hover) { .wiz-action-2nd:hover:not(:disabled) { background: #f4f6f9; border-color: #c8d3e3; color: #26375a; } }
.wiz-action-2nd.is-open { background: #eef1f6; border-color: #b9c4da; color: #26375a; }
.wiz-action-2nd.is-done { border-color: #7db98c; color: #2f8a45; background: color-mix(in srgb, #34a853 8%, #fff); }
.wiz-action-2nd:disabled { opacity: 1; cursor: not-allowed; color: #98a3b5; border-color: #e6eaf1; background: #fafbfc; }

.wiz-action-restart {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  /* Smaller + a proper filled-grey secondary button instead of the ghosty outline
     that "sucked" (#img381). */
  padding: 0.6rem 1.05rem;
  background: #eef1f6;
  border: 1px solid #e1e6ee;
  border-radius: 10px;
  color: #475569;
  font-family: var(--font-family);
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition: border-color 0.12s, color 0.12s, background 0.12s, opacity 0.12s;
  min-height: 40px;
}
@media (hover: hover) { .wiz-action-restart:hover:not(:disabled) {
  border-color: #cdd6e3;
  color: #26375a;
  background: #e4e9f1;
} }
.wiz-action-restart:disabled {
  /* Still clearly a button when nothing's added — just a touch muted (#img394). */
  opacity: 1;
  cursor: not-allowed;
  border-color: #e1e6ee;
  color: #64748b;
  background: #eef1f6;
}

@media (max-width: 640px) {
  /* Submit full-width up top, then Clear · Preview · Export share the next row as
     equal thirds (Clear first) — no cramped wrapping (#img12). */
  .wiz-action-buttons { gap: 8px; }
  .wiz-action-btn { flex: 1 1 100%; width: 100%; min-width: 0; padding: 0.7rem 1rem; font-size: 0.9rem; order: 1; }
  .wiz-action-buttons .wiz-action-restart { flex: 1 1 0; width: auto; min-width: 0; margin-left: 0; padding: 0.6rem 0.5rem; font-size: 0.82rem; order: 2; }
  .wiz-action-2nd { flex: 1 1 0; min-width: 0; padding: 0.6rem 0.5rem; font-size: 0.85rem; order: 3; }
}

@media (max-width: 640px) {
  .wiz-field-row {
    grid-template-columns: 1fr;
    gap: 1rem;
  }
}

/* Prompt generator now uses .prompt-modal-overlay / .prompt-modal-panel
   styles for its preview+submit modal — see the Prompt Modal section. */

.pm-preview.is-empty { color: var(--color-text-muted); font-style: italic; }

/* Topic picker: search-modal-style with multi-select checkmarks */
.wiz-topic-picker-card {
  max-width: 480px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  /* Card sizes to its content. Cap = 80vh so long lists scroll. */
  max-height: 80vh;
}
.wiz-topic-picker-card .search-overlay-body {
  /* flex: 0 1 auto means body grows to its content but won't fill
     remaining card space — so Done sits right below the options
     when the list is short instead of stuck to viewport bottom. */
  flex: 0 1 auto;
  overflow-y: auto;
  min-height: 0;
}
@media (max-width: 640px) {
  .wiz-topic-picker-card {
    max-width: none;
    max-height: 90dvh;
    border-radius: 12px 12px 0 0;
  }
  .wiz-topic-overlay {
    padding: 0;
    align-items: flex-end;
  }
}
.wiz-topic-picker-header {
