}
.wiz-topic-check {
  width: 18px;
  height: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.65rem;
  color: white;
  font-weight: var(--font-weight-bold);
  flex-shrink: 0;
  border: 1.5px solid var(--color-border);
  border-radius: 50%;
  background: var(--color-bg);
  transition: background 0.12s, border-color 0.12s;
}
.wiz-topic-row.is-selected .wiz-topic-check,
.wiz-topic-result.is-selected .wiz-topic-check {
  background: #22c55e;
  border-color: #22c55e;
}
.wiz-topic-row {
  cursor: pointer;
}
.wiz-topic-row.is-selected {
  background: var(--color-accent);
}
/* Parent rows in topic picker — clearly clickable */
.wiz-topic-picker-card .search-parent-row {
  cursor: pointer;
}
@media (hover: hover) { .wiz-topic-picker-card .search-parent-row:hover {
  background: #e8eaef;
} }
.wiz-topic-parent-hint {
  margin-left: auto;
  font-size: 0.75rem;
  color: var(--color-text-light);
}
.wiz-topic-result {
  cursor: pointer;
}
.wiz-topic-result.is-selected {
  background: var(--color-accent);
}
.wiz-topic-picker-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.65rem 1rem;
  padding-bottom: calc(0.65rem + env(safe-area-inset-bottom, 0px));
  border-top: 1px solid var(--color-border);
  background: var(--color-bg-light, #f6f7f9);
  position: sticky;
  bottom: 0;
  z-index: 10;
  flex-shrink: 0;
}
.wiz-topic-picker-foot-left {
  justify-content: flex-start;
}
.wiz-topic-picker-count {
  color: var(--color-text-muted);
  font-size: 0.8rem;
}
.wiz-topic-picker-title-block {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}
.wiz-topic-picker-desc {
  font-size: 0.78rem;
  color: var(--color-text-muted);
  font-weight: var(--font-weight-regular);
  margin: 0;
  line-height: 1.35;
}
.wiz-custom-badge-inline {
  display: inline-block;
  margin-left: 0.4rem;
  padding: 0.05rem 0.4rem;
  background: var(--color-accent);
  color: var(--color-text-muted);
  font-size: 0.65rem;
  font-weight: var(--font-weight-medium);
  border-radius: 3px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  vertical-align: middle;
}
.wiz-field-add-row {
  cursor: pointer;
  border: 1px dashed var(--color-border);
  border-radius: 5px;
  padding: 0.55rem 0.7rem;
  margin-bottom: 0.4rem;
  background: var(--color-bg-light, #f6f7f9);
