}
@media (hover: hover) { .wiz-field-add-row:hover {
  border-color: var(--color-primary);
  background: var(--color-accent);
} }
.wiz-topic-picker-done {
  padding: 0.45rem 1.1rem;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 4px;
  font-weight: var(--font-weight-semibold);
  font-size: 0.85rem;
  cursor: pointer;
}
@media (hover: hover) { .wiz-topic-picker-done:hover { background: var(--color-primary-dark, #162238); } }

/* Legacy .wiz — keep for any remaining styles */
.wiz {
  max-width: 720px;
  margin: 0;
  display: flex;
  flex-direction: column;
  background: var(--color-bg);
}

/* Clickable horizontal stepper — compact numbered markers, all 8
   visible at once. Only the CURRENT step also shows its label so the
   row never overflows. The label for other steps is a hover tooltip. */

.wiz-step {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.25rem 0.3rem;
  background: transparent;
  border: none;
  border-radius: 999px;
  cursor: pointer;
  font-family: var(--font-family);
  color: var(--color-text-muted);
  white-space: nowrap;
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s;
}

@media (hover: hover) { .wiz-step:hover:not(.is-blocked) {
  background: var(--color-bg-light);
  color: var(--color-text);
} }

.wiz-step.is-blocked {
  cursor: not-allowed;
  opacity: 0.45;
}

.wiz-step-marker {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--color-bg-muted);
  color: var(--color-text-muted);
  font-size: 0.74rem;
  font-weight: var(--font-weight-bold);
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s, box-shadow 0.15s;
}

.wiz-step-label {
  font-weight: var(--font-weight-bold);
  font-size: 0.82rem;
  letter-spacing: -0.01em;
}

.wiz-step-sep {
  flex: 1;
  height: 3px;
  background: var(--color-border);
  margin: 0 0.2rem;
  border-radius: 2px;
  min-width: 12px;
}

/* Separator after a completed step fills with primary to show progress. */
.wiz-step.is-complete + .wiz-step-sep,
.wiz-step.is-current + .wiz-step-sep {
  background: linear-gradient(to right, var(--color-primary) 50%, var(--color-border) 50%);
}
.wiz-step.is-complete:has(+ .wiz-step-sep + .wiz-step.is-complete) + .wiz-step-sep,
.wiz-step.is-complete:has(+ .wiz-step-sep + .wiz-step.is-current) + .wiz-step-sep {
  background: var(--color-primary);
}

/* States */
.wiz-step.is-current {
  color: var(--color-primary);
  background: var(--color-accent);
  padding-right: 0.7rem;
}
.wiz-step.is-current .wiz-step-marker {
  background: var(--color-primary);
  color: white;
  box-shadow: 0 0 0 3px white, 0 0 0 5px var(--color-primary);
}

.wiz-step.is-complete .wiz-step-marker {
  background: var(--color-primary);
  color: white;
}
.wiz-step.is-complete {
  color: var(--color-primary);
}

.wiz-step.is-visited:not(.is-current):not(.is-complete) {
  color: var(--color-text);
}
.wiz-step.is-visited:not(.is-current):not(.is-complete) .wiz-step-marker {
  background: var(--color-bg-light);
  color: var(--color-text);
  border: 1.5px solid var(--color-border);
}

.wiz-step.is-future {
  opacity: 0.55;
}

@media (max-width: 640px) {

  .wiz-step-marker {
    width: 24px;
    height: 24px;
    font-size: 0.7rem;
  }

  .wiz-step-label {
    font-size: 0.72rem;
  }

  .wiz-step.is-current {
    padding-right: 0.5rem;
  }

  .wiz-step-sep {
    min-width: 8px;
  }
}

/* Very narrow widths — hide labels for non-current steps to keep tracker compact */
@media (max-width: 440px) {
  .wiz-step:not(.is-current) .wiz-step-label {
    display: none;
  }
}

.wiz-step-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: var(--font-weight-bold);
  color: var(--color-text);
  letter-spacing: -0.015em;
  line-height: 1.25;
  margin: 0 0 0.35rem;
}

.wiz-step-desc {
  font-size: 0.85rem;
  color: var(--color-text-muted);
  line-height: 1.5;
  margin: 0 0 1rem;
}

.wiz-step-content {
  margin-bottom: 1rem;
}

/* Inputs */
.wiz-label {
  display: block;
  font-family: var(--font-display);
  font-size: 0.95rem;
  color: var(--color-text);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.01em;
  margin-bottom: 0.55rem;
}

.wiz-required {
  color: var(--color-primary);
}

.wiz-optional {
  color: var(--color-text-light);
  font-weight: var(--font-weight-regular);
  font-size: 0.85em;
}

.wiz-input {
  width: 100%;
  padding: 0.7rem 0.85rem;
  border: 2px solid var(--color-border);
  border-radius: 8px;
  /* 16px floor on every PB input — anything smaller triggers iOS
     Safari's auto-zoom on focus, which was bouncing the page when
     the user tapped a custom field. */
  font-size: 16px;
  font-family: var(--font-family);
  color: var(--color-text);
  background: white;
  transition: border-color 0.15s;
}

.wiz-input:focus {
  outline: none;
  border-color: var(--color-primary);
}

.wiz-textarea {
  width: 100%;
  padding: 0.7rem 0.85rem;
  border: 2px solid var(--color-border);
  border-radius: 8px;
  font-size: 16px;
  font-family: var(--font-family);
  color: var(--color-text);
  background: white;
  min-height: 90px;
  resize: vertical;
  transition: border-color 0.15s;
}

.wiz-textarea:focus {
  outline: none;
  border-color: var(--color-primary);
}

/* Popular topic chips on Step 1 */

/* Card grid (Content Type) */
.wiz-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.65rem;
}

.wiz-card {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 0.85rem 0.9rem;
  border: 1px solid var(--color-surface-border);
  background: #fff;
  border-radius: 11px;
  cursor: pointer;
  font-family: var(--font-family);
  text-align: left;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s, transform 0.05s;
}

@media (hover: hover) { .wiz-card:hover {
  border-color: color-mix(in srgb, var(--color-primary) 30%, var(--color-surface-border));
  background: color-mix(in srgb, var(--color-primary) 3%, #fff);
} }

.wiz-card.selected {
  border-color: var(--color-primary);
  background: color-mix(in srgb, var(--color-primary) 7%, #fff);
  box-shadow: inset 0 0 0 1px var(--color-primary);
}

.wiz-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 0.5rem;
  color: #2c4467;
  line-height: 1;
}
.wiz-card-icon svg { width: 24px; height: 24px; display: block; }

.wiz-card-label {
  font-size: 0.92rem;
  font-weight: var(--font-weight-semibold);
  color: var(--color-text);
  letter-spacing: -0.01em;
}

.wiz-card.selected .wiz-card-label {
  color: var(--color-primary);
}

/* Chip grid (most steps) */
.wiz-chip-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  margin-left: -0.1rem;
}

.wiz-chip {
  padding: 0.3rem 0.65rem;
  border: 1.5px solid var(--color-border);
  background: white;
  border-radius: 999px;
  font-size: 0.78rem;
  font-family: var(--font-family);
  color: var(--color-text);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, color 0.15s;
}

@media (hover: hover) { .wiz-chip:hover {
  border-color: var(--color-primary-light);
  background: var(--color-bg-light);
} }

.wiz-chip.selected {
  border-color: #4a6a8a;
  background: #4a6a8a;
  color: white;
}

/* Custom value chip (selected by default, has remove button) */
.wiz-chip.wiz-chip-custom {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding-right: 0.4rem;
}

.wiz-chip-remove {
  background: rgba(255, 255, 255, 0.18);
  color: white;
  border: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  font-size: 0.8rem;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

@media (hover: hover) { .wiz-chip-remove:hover {
  background: rgba(255, 255, 255, 0.32);
} }

/* "+ Add custom" chip — quiet, outlined, dashed */
.wiz-chip-add {
  border-style: dashed;
  border-color: var(--color-border);
  background: transparent;
  color: var(--color-text-muted);
  font-weight: var(--font-weight-medium);
}

@media (hover: hover) { .wiz-chip-add:hover {
  border-style: solid;
  border-color: var(--color-primary);
  background: var(--color-accent);
  color: var(--color-primary);
} }

/* Custom card (for content type step) */
.wiz-card.wiz-card-custom {
  position: relative;
}

.wiz-card-remove {
  position: absolute;
  top: 0.4rem;
  right: 0.4rem;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(30, 45, 68, 0.1);
  color: var(--color-primary);
  border: none;
  font-size: 0.95rem;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}

@media (hover: hover) { .wiz-card-remove:hover {
  background: var(--color-primary);
  color: white;
} }

.wiz-card.wiz-card-add {
  border-style: dashed;
  border-color: var(--color-border);
  background: transparent;
  color: var(--color-text-muted);
}

@media (hover: hover) { .wiz-card.wiz-card-add:hover {
  border-style: solid;
  border-color: var(--color-primary);
  background: var(--color-accent);
  color: var(--color-primary);
} }

.wiz-card.wiz-card-add .wiz-card-icon,
.wiz-card.wiz-card-add .wiz-card-label {
  color: var(--color-primary);
}

/* Inline custom-input wrap (replaces the "+ Add custom" chip when clicked) */
.wiz-custom-input-wrap {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  border: 2px solid var(--color-primary);
  background: white;
  border-radius: 999px;
  padding: 0.25rem 0.4rem 0.25rem 0.85rem;
}

.wiz-custom-input {
  border: none;
  outline: none;
  font-family: var(--font-family);
  font-size: 16px;
  background: transparent;
  color: var(--color-text);
  width: 180px;
  min-width: 100px;
  padding: 0;
}

.wiz-custom-add-btn {
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 999px;
  padding: 0.3rem 0.75rem;
  font-size: 0.78rem;
  font-weight: var(--font-weight-semibold);
  font-family: var(--font-family);
  cursor: pointer;
}

@media (hover: hover) { .wiz-custom-add-btn:hover {
  background: var(--color-primary-dark);
} }

.wiz-custom-cancel-btn {
  background: none;
  color: var(--color-text-muted);
  border: none;
  padding: 0.2rem 0.4rem;
  font-size: 0.95rem;
  cursor: pointer;
  line-height: 1;
}

@media (hover: hover) { .wiz-custom-cancel-btn:hover {
  color: var(--color-text);
} }

/* Extra inputs (for requiresInput options like "Compare to what?") */
.wiz-extras {
  margin-top: 0.75rem;
}

.wiz-extra-input {
  margin-bottom: 0.75rem;
  padding: 0.7rem 0.85rem;
  background: var(--color-accent);
  border-radius: 8px;
  border-left: 3px solid var(--color-primary);
}

.wiz-extra-input:last-child {
  margin-bottom: 0;
}

.wiz-extra-label {
  display: block;
  font-size: 0.78rem;
  color: var(--color-text);
  font-weight: var(--font-weight-semibold);
  margin-bottom: 0.4rem;
}

.wiz-extra-context {
  color: var(--color-text-muted);
  font-weight: var(--font-weight-regular);
  font-size: 0.85em;
}

.wiz-extra-field {
  font-size: 16px !important;
  padding: 0.5rem 0.75rem !important;
}

/* Sub-sections render as card blocks — each pick category gets its
   own bordered card with a clear heading, then the field UI inside.
   Matches the Topics modal / Settings modal card pattern so the
   Prompt Builder reads as a related family of pickers. */
.wiz-sub-section {
  background: var(--color-bg);
  border: 1px solid #e6e8ec;
  border-radius: 12px;
  padding: 0.95rem 1.05rem 1rem;
  margin-bottom: 0.85rem;
  box-shadow: 0 1px 2px rgba(15, 26, 46, 0.03);
  transition: border-color 0.14s, box-shadow 0.14s;
}
.wiz-sub-section:last-child { margin-bottom: 0; }
.wiz-sub-section:focus-within {
  border-color: #c8d3e3;
  box-shadow: 0 2px 6px rgba(15, 26, 46, 0.06);
}

.wiz-sub-label {
  display: block;
  font-family: var(--font-display);
  font-size: 1rem;
  color: #1e2d44;
  font-weight: 700;
  letter-spacing: -0.012em;
  margin-bottom: 0.65rem;
  line-height: 1.2;
}
.wiz-sub-label .wiz-optional {
  font-family: var(--font-family);
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--color-text-muted);
  margin-left: 0.35rem;
  letter-spacing: -0.005em;
}

/* On wider viewports, the Style step (which is mostly chip-grid
   pickers) and the Content step lay their card blocks out in a
   responsive 2-column grid for a denser, more "settings-like"
   read. Steps add the class on their root, e.g. .wiz-step-body. */
@media (min-width: 720px) {
  .wiz-step-body.wiz-grid-2 {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.85rem;
  }
  .wiz-step-body.wiz-grid-2 .wiz-sub-section { margin-bottom: 0; }
  /* Full-width card for the Custom Instructions textarea so it
     gets the breathing room it needs. */
  .wiz-step-body.wiz-grid-2 .wiz-sub-section.wiz-sub-section-wide {
    grid-column: 1 / -1;
  }
}

/* Live prompt preview — neutral but with real presence */
.wiz-preview {
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  margin-bottom: 1rem;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
}

.wiz-preview-head {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.6rem 0.95rem;
  background: var(--color-bg-light, #f6f7f9);
  border-bottom: 1px solid var(--color-border);
  font-family: var(--font-display);
  font-size: 0.78rem;
  font-weight: var(--font-weight-bold);
  color: var(--color-text);
  letter-spacing: -0.005em;
}
.wiz-preview-head::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--color-primary);
  flex-shrink: 0;
}

.wiz-preview-body {
  padding: 0.85rem 0.95rem;
  font-size: 0.9rem;
  line-height: 1.6;
  color: var(--color-text);
  white-space: pre-wrap;
  background: var(--color-bg);
}

.wiz-preview-body.wiz-preview-empty {
  color: var(--color-text-light);
  font-style: italic;
}

/* Footer nav */

.wiz-btn-back,
.wiz-btn-skip,
.wiz-btn-next {
  padding: 0.6rem 1.1rem;
  border-radius: 6px;
  font-size: 0.88rem;
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  font-family: var(--font-family);
  transition: background 0.15s, color 0.15s, border-color 0.15s;
}

.wiz-btn-back {
  background: transparent;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
}

@media (hover: hover) { .wiz-btn-back:hover:not(:disabled) {
  border-color: var(--color-primary-light);
  color: var(--color-text);
} }

.wiz-btn-back:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.wiz-btn-skip {
  background: transparent;
  color: var(--color-text-muted);
  border: none;
}

@media (hover: hover) { .wiz-btn-skip:hover {
  color: var(--color-text);
} }

.wiz-btn-next {
  background: var(--color-primary);
  color: white;
  border: none;
}

@media (hover: hover) { .wiz-btn-next:hover:not(:disabled) {
  background: var(--color-primary-dark);
} }

.wiz-btn-next:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* Review step */
.wiz-review {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.wiz-review-section {
  display: flex;
  flex-direction: column;
}

.wiz-prompt-box {
  background: var(--color-bg-light, #f6f7f9);
  color: var(--color-text);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  padding: 1rem 1.15rem;
  font-size: 0.92rem;
  line-height: 1.6;
  white-space: pre-wrap;
  margin-bottom: 0.6rem;
  max-height: 320px;
  overflow-y: auto;
}

.wiz-prompt-edit {
  width: 100%;
  min-height: 240px;
  max-height: 420px;
  padding: 1rem 1.15rem;
  background: var(--color-bg);
  color: var(--color-text);
  border: 1.5px solid var(--color-primary);
  border-radius: 4px;
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.6;
  resize: vertical;
  outline: none;
  margin-bottom: 0.6rem;
}

.wiz-review-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.45rem;
}

.wiz-review-actions {
  display: flex;
  gap: 0.35rem;
}

.wiz-btn-inline {
  padding: 0.3rem 0.7rem;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: 4px;
  color: var(--color-text);
  font-size: 0.78rem;
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}
@media (hover: hover) { .wiz-btn-inline:hover {
  background: var(--color-accent);
  border-color: var(--color-primary);
  color: var(--color-primary);
} }

.wiz-prompt-reset {
  background: transparent;
  border: none;
  color: var(--color-text-muted);
  font-size: 0.78rem;
  text-decoration: underline;
  text-underline-offset: 2px;
  cursor: pointer;
  padding: 0.2rem 0;
}
@media (hover: hover) { .wiz-prompt-reset:hover { color: var(--color-primary); } }

/* Prompt generator: step pills in the sticky subnav */

/* "Preview" action in the prompt-generator subnav — opens the live
   prompt preview modal from anywhere in the wizard. */
@keyframes wiz-subnav-preview-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

/* Live prompt preview modal */
.prompt-preview-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 1000;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}
.prompt-preview-modal-card {
  position: relative;
  background: var(--color-surface);
  border-radius: 6px;
  width: 100%;
  max-width: 620px;
  max-height: 82vh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 25px 60px rgba(15, 23, 42, 0.35);
  animation: modalPop 0.18s ease-out;
}
.prompt-preview-modal-close {
  position: absolute;
  top: 0.6rem;
  right: 0.75rem;
  width: 32px;
  height: 32px;
  background: transparent;
  border: none;
  border-radius: 4px;
  color: var(--color-text-muted);
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}
@media (hover: hover) { .prompt-preview-modal-close:hover {
  background: var(--color-bg-light);
  color: var(--color-text);
} }
.prompt-preview-modal-head {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 1.15rem 0.85rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-bg-light, #f6f7f9);
}
.prompt-preview-modal-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--color-primary);
  flex-shrink: 0;
}
.prompt-preview-modal-title {
  font-family: var(--font-display);
  font-size: 0.95rem;
  font-weight: var(--font-weight-bold);
  color: var(--color-text);
  letter-spacing: -0.01em;
  margin: 0;
}
.prompt-preview-modal-body {
  flex: 1;
  overflow-y: auto;
  padding: 1.15rem 1.25rem;
  font-size: 0.92rem;
  line-height: 1.65;
  color: var(--color-text);
  white-space: pre-wrap;
}
.prompt-preview-modal-body.is-empty {
  color: var(--color-text-light);
  font-style: italic;
  text-align: center;
  padding: 2rem 1.25rem;
}
.prompt-preview-modal-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem 1.15rem;
  border-top: 1px solid var(--color-border);
  background: var(--color-bg-light, #f6f7f9);
}
.prompt-preview-modal-copy {
  padding: 0.45rem 0.9rem;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 4px;
  font-size: 0.82rem;
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition: background 0.15s;
}
@media (hover: hover) { .prompt-preview-modal-copy:hover {
  background: var(--color-primary-dark, var(--color-primary));
} }
.prompt-preview-modal-hint {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}
.wiz-subnav-step.is-complete:not(.active) .wiz-subnav-num {
  background: var(--color-primary);
  color: white;
  border-color: var(--color-primary);
}
.wiz-subnav-step.is-complete:not(.active) {
  color: var(--color-text);
}

.wiz-btn-secondary {
  align-self: flex-start;
  padding: 0.45rem 0.9rem;
  background: white;
  color: var(--color-text-muted);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  font-size: 0.82rem;
  font-weight: var(--font-weight-medium);
  cursor: pointer;
  font-family: var(--font-family);
}

@media (hover: hover) { .wiz-btn-secondary:hover {
  border-color: var(--color-primary-light);
  color: var(--color-text);
} }

.wiz-model-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0.5rem;
}

.wiz-model-btn {
  padding: 0.65rem 0.5rem;
  border: 2px solid var(--color-border);
  background: white;
  border-radius: 8px;
  font-size: 0.85rem;
  cursor: pointer;
  font-family: var(--font-family);
  color: var(--color-text);
  text-align: center;
  transition: border-color 0.15s, background 0.15s;
}

@media (hover: hover) { .wiz-model-btn:hover {
  border-color: var(--color-primary-light);
} }

.wiz-model-btn.selected {
  border-color: var(--color-primary);
  background: var(--color-accent);
  color: var(--color-primary);
  font-weight: var(--font-weight-semibold);
}

.wiz-model-tag {
  font-size: 0.7em;
  color: var(--color-text-light);
}

.wiz-warning {
  padding: 0.7rem 0.85rem;
  background: #fffbeb;
  border: 1px solid #f6e05e;
  color: #744210;
  border-radius: 6px;
  font-size: 0.82rem;
  line-height: 1.5;
}

.wiz-btn-submit {
  width: 100%;
  padding: 0.95rem;
  background: var(--color-primary);
  color: white;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: var(--font-weight-bold);
  cursor: pointer;
  font-family: var(--font-family);
  letter-spacing: -0.01em;
  transition: background 0.15s;
}

@media (hover: hover) { .wiz-btn-submit:hover {
  background: var(--color-primary-dark);
} }

.wiz-btn-restart {
  width: 100%;
  padding: 0.7rem;
  background: transparent;
  color: var(--color-text-muted);
  border: none;
  font-size: 0.82rem;
  cursor: pointer;
  font-family: var(--font-family);
  text-decoration: underline;
  text-decoration-color: rgba(113, 128, 150, 0.3);
  text-underline-offset: 3px;
}

@media (hover: hover) { .wiz-btn-restart:hover {
  color: var(--color-primary);
} }

.wiz-disclaimer {
  font-size: 0.72rem;
  color: var(--color-text-light);
  text-align: center;
  line-height: 1.5;
  margin: 0;
}

/* Mobile */
@media (max-width: 640px) {
  .wiz-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .wiz-step-title {
    font-size: 1.1rem;
  }

  .wiz-step-desc {
    font-size: 0.82rem;
    margin-bottom: 0.85rem;
  }

  .wiz-model-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .wiz-btn-back,
  .wiz-btn-skip,
  .wiz-btn-next {
    padding: 0.55rem 0.85rem;
    font-size: 0.82rem;
  }
}

@media (max-width: 400px) {
  .wiz-cards {
    grid-template-columns: 1fr;
  }

  .wiz-model-grid {
    grid-template-columns: 1fr;
  }
}

/* === About Page === */
/* Static pages (About / Terms) — restyled to match the current site language
   (#img90-93/97): the subnav carries the page title, so content opens with a
   lead line; deep-navy display headers; grey pill buttons like the pickers. */
.about-page {
  max-width: 720px;
  padding-top: 0.35rem;
}
.about-lead {
  font-size: 1.02rem;
  color: #33415c;
  line-height: 1.65;
  margin: 0 0 0.6rem;
}
.about-updated {
  font-size: 0.78rem; font-weight: 600; color: var(--color-text-muted);
  margin: 0 0 1.4rem;
}
.about-page > .about-lead:last-of-type { margin-bottom: 1.8rem; }
.about-section {
  margin-bottom: 1.6rem;
  padding-bottom: 1.6rem;
  border-bottom: 1px solid #e9edf3;
}
.about-section:last-child {
  border-bottom: none;
  padding-bottom: 0;
}
.about-section h3 {
  font-family: var(--font-display);
  font-size: 1.12rem;
  font-weight: 700;
  color: #1a2740;
  letter-spacing: -0.01em;
  margin-bottom: 0.6rem;
}
.about-section p {
  font-size: 0.9rem;
  line-height: 1.7;
  color: #33415c;
  margin: 0 0 0.85rem;
}
.about-section p:last-child { margin-bottom: 0; }
.about-section ul + p,
.about-section p + p { margin-top: 0; }
.about-section ul {
  padding-left: 1.15rem;
  font-size: 0.9rem;
  line-height: 1.7;
  color: #33415c;
  list-style: none;
  margin: 0 0 0.85rem;
}
.about-section li {
  margin-bottom: 0.45rem;
  position: relative;
  padding-left: 0.15rem;
}
.about-section li::before {
  content: '';
  position: absolute;
  left: -1rem;
  top: 0.62em;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: #8fa3c4;
}
.about-section li strong,
.about-section p strong { color: #1a2740; }
.about-section a { color: #1d4ed8; font-weight: 600; text-decoration: none; }
@media (hover: hover) { .about-section a:hover { text-decoration: underline; } }
/* CTA button links (Portfolio, LinkedIn, GitHub) — same grey pill family as the
   topic-picker buttons. */
.about-cta-row {
  display: flex;
  gap: 0.5rem;
  margin-top: 0.75rem;
  flex-wrap: wrap;
}
.about-cta-link {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin-top: 0.5rem;
  padding: 7px 14px;
  background: #eef1f6;
  border: 1px solid #dde3ee;
  border-radius: 999px;
  font-size: 0.82rem;
  font-weight: 600;
  color: #26375a !important;
  text-decoration: none !important;
  transition: background 0.13s, border-color 0.13s;
}
@media (hover: hover) { .about-cta-link:hover {
  background: #e3e9f4;
  border-color: #ccd6e8;
  text-decoration: none !important;
} }
.about-cta-row .about-cta-link { margin-top: 0; }
/* Closing note — soft card instead of another plain section. Class doubled so it
   out-ranks .about-section:last-child's padding-bottom reset. */
.about-section.about-disclaimer {
  background: #f7f9fc;
  border: 1px solid #e6ebf3;
  border-radius: 12px;
  padding: 1rem 1.15rem;
}
.about-disclaimer p {
  font-size: 0.86rem;
  color: #4a5a75;
  line-height: 1.65;
}

/* === Not Found === */
.not-found {
  text-align: center;
  padding: 3rem 1rem;
}

.not-found h2 {
  margin-bottom: 0.5rem;
}

/* === Typography === */
body {
  font-weight: var(--font-weight-regular);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  letter-spacing: -0.01em;
}

h1, h2, h3, h4, .section-header h2 {
  font-family: var(--font-display);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.02em;
}

.section-header h2 {
  font-weight: var(--font-weight-semibold);
}

.tab-pill,
.shortcut-name {
  font-weight: var(--font-weight-medium);
}

.tab-pill.active {
  font-weight: var(--font-weight-semibold);
}

.prompt-modal-label,
.search-result-header,
.search-result-section-label {
  font-weight: var(--font-weight-semibold);
}

/* === Enhanced Search Bar (prominent) === */
.search-bar {
  padding: 0.85rem 1.1rem;
  font-size: 0.95rem;
  font-weight: var(--font-weight-medium);
  gap: 0.7rem;
  border-radius: 8px;
  width: 100%;
}

.search-bar-icon {
  font-size: 1.1rem;
  flex-shrink: 0;
  color: var(--color-primary);
}

.search-bar-label {
  flex: 1;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}

.search-bar-wrapper {
  flex: 1 1 auto;
  min-width: 0;
  width: 100%;
}

/* === Prompt Generator extras === */

/* === Topic Banner (with integrated tabs) === */
.topic-banner {
  background: transparent;
  border: none;
  border-bottom: 1px solid rgba(30, 45, 68, 0.12);
  border-radius: 0;
  margin-bottom: 1.5rem;
  padding: 0.25rem 0 1.15rem;
}

.topic-banner-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 1.25rem;
  flex-wrap: wrap;
  row-gap: 0.6rem;
}

/* TP3: subtle vertical divider between title group and tabs */
.topic-banner-row .topic-banner-tabs {
  position: relative;
  padding-left: 1.25rem;
}

.topic-banner-row .topic-banner-tabs::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 22px;
