/* --- AI Actions cards ------------------------------------------------- */

/* Group accent palette — each group gets its own tint on the
   eyebrow label + card icon. Subtle on the card itself so the
   reading rhythm comes from the name + description, not a wash
   of color across the row. */
.ti-action-group { --ti-accent: #5d6b7e; }
.ti-action-group--discover { --ti-accent: #3261a0; }
.ti-action-group--learn    { --ti-accent: #2e8a73; }
.ti-action-group--analyze  { --ti-accent: #b48528; }
.ti-action-group--more     { --ti-accent: #8a4f7a; }

.ti-action-group + .ti-action-group { margin-top: 0.35rem; }
.ti-action-group-label {
  /* Section header: title-case dark text + a thin tall accent bar
     to its left. No underline — the row's identity is the chip +
     larger label text, not a separator rule. */
  color: #1a2235;
  font-weight: 700;
  letter-spacing: -0.014em;
  font-size: 1rem;
  text-transform: none;
  margin: 0 0 0.45rem;
  padding-bottom: 0;
  border-bottom: none;
  display: flex;
  align-items: center;
  /* No `gap` here — the chip's margin-right is the ONLY space
     between chip and label, matching Web Sources's layout. A
     stray flex gap was previously adding ~0.5rem on top of the
     margin, which made Discover / Learn / Analyze / More look
     visibly farther from their chips than Web Sources. */
}
/* Accent chip — thin tall colored bar to the left of the section
   label text. Carries the section's color identity. Slightly
   bigger than the header text height so it reads as a confident
   "this section is X" marker. */
.ti-action-group-label::before {
  content: '';
  display: inline-block;
  width: 3px;
  height: 22px;
  background: var(--ti-accent);
  border-radius: 2px;
  /* Identical spacing to Web Sources (0.55rem) — uniform value
     across every section header chip. */
  margin-right: 0.55rem;
  flex-shrink: 0;
}
.ti-action-group-label::after { display: none; }

.ti-action-cards {
  list-style: none;
  margin: 0;
  padding: 0 0.25rem 0 0;
  display: flex;
  flex-direction: column;
  /* No gap — consecutive rows' left accent rules stack into one
     continuous spine per group, visually unifying the four DISCOVER
     rows (etc.) without any card chrome. */
  gap: 0;
}
.ti-action-card-row { margin: 0; padding: 0; }

/* Flat row — no card chrome. A 2px left accent rule (in the group
   color, muted) carries identity; consecutive rows in the same group
   stack so their rules form one continuous spine. Hover and selected
   states tint the row background and bring the rule to full accent.
   Reads as a list of capabilities, not a deck of products. */
.shortcuts-sidebar .sidebar-shortcut.ti-action-card {
  display: flex;
  flex-direction: column;
  /* Override the underlying .ai-shortcut-select-btn rule's
     align-items: center — in a flex column that horizontally
     centers children, which would shrink the description to
     content-width and center it instead of stretching across
     the full card width. */
  align-items: stretch;
  gap: 0.28rem;
  width: 100%;
  padding: 0.55rem 0.7rem 0.6rem 0.7rem;
  background: transparent;
  border: none;
  border-radius: 0;
  text-align: left;
  font-family: var(--font-family);
  cursor: pointer;
  color: var(--color-text);
  transition: background 0.16s;
}
.ti-action-card-header {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-width: 0;
  width: 100%;
}
/* Icon slot — no background, no border-radius, no padding. Just
   the glyph itself in the group's accent color. The 20px box gives
   the SVG room to breathe and acts as the multi-select check
   "anchor" — when selected, an accent-filled rounded square fills
   this slot and shows a white check. */
.ti-action-card-icon {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 15px;
  height: 15px;
  border-radius: 5px;
  background: transparent;
  /* Single neutral icon color across all sections — the accent
     work now lives on the section-label chip instead, keeping
     the row content (icon + name + description) reading as
     uniform content rather than color-coded by section. */
  color: #6c7589;
  flex-shrink: 0;
}
.ti-action-card-icon-svg {
  width: 13px;
  height: 13px;
  color: inherit;
  stroke-width: 1.5;
}

/* === Inline-SVG shortcut icon ====================================
   Icon SVGs are inlined from the build-generated registry so
   stroke="currentColor" resolves to the parent's CSS color
   directly. Section-accent tinting (color: var(--ti-accent)
   on the wrapper) propagates automatically. */
.shortcut-icon {
  display: inline-block;
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  color: inherit;
}
.shortcuts-sidebar .ti-action-card .ti-action-card-name {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 0.8rem;
  font-weight: 600;
  line-height: 1.28;
  letter-spacing: -0.01em;
  color: #1a2235;
  /* Allow long titles to wrap to a second line within the header
     row — sits to the right of the inline glyph naturally. */
  white-space: normal;
  word-break: break-word;
}
.ti-action-card-desc {
  display: block;
  font-size: 0.7rem;
  font-weight: 400;
  line-height: 1.4;
  letter-spacing: -0.002em;
  color: #6a7689;
  /* Description spans the full card width — no indent under the
     icon. Reads as a continuation of the title row rather than a
     subordinate paragraph aligned with a separate icon column. */
  margin: 0;
}

/* Hover state — row picks up a soft accent tint. No spine, no
   border, no shadow: the tint alone signals interactivity. */
@media (hover: hover) {
  .shortcuts-sidebar .sidebar-shortcut.ti-action-card:hover {
    background: color-mix(in srgb, var(--ti-accent) 5%, transparent);
  }
}

/* Multi-select state — the small icon slot fills with a rounded
   accent square + white check (reads as a ticked checkbox), the row
   tints accent, and the left rule resolves to full accent. No
   border / box-shadow on the row itself — the tint + rule + check
   carry the state without re-introducing card chrome. */
.ti-action-card-marker {
  position: absolute;
  inset: 0;
  display: none;
  border-radius: 4px;
  background: var(--ti-accent);
  color: #fff;
  align-items: center;
  justify-content: center;
}
.ti-action-card-check { color: #fff; }
.shortcuts-sidebar .sidebar-shortcut.ti-action-card.is-multi-selected {
  background: color-mix(in srgb, var(--ti-accent) 9%, transparent);
}
.shortcuts-sidebar .sidebar-shortcut.ti-action-card.is-multi-selected
  .ti-action-card-marker { display: inline-flex; }
.shortcuts-sidebar .sidebar-shortcut.ti-action-card.is-multi-selected
  .ti-action-card-icon-svg { visibility: hidden; }
.shortcuts-sidebar .sidebar-shortcut.ti-action-card.is-multi-selected
  .ti-action-card-name { color: var(--ti-accent); }

/* Hide the legacy bullet marker on cards (it was the original
   selection indicator before the card redesign — keeping the
   .ai-shortcut-marker classname intact so the existing JS still
   works, but visually we replaced it with the icon-overlay check
   above). */
.ti-action-card .ai-shortcut-marker-dot { display: none; }

/* Mobile (tabbed mode): cards get more room since the sidebar
   fills the viewport. Icon glyph and type sizes step up so the
   card reads comfortably from arm's length on a phone. */
@media (max-width: 899.98px) {
  /* Mobile shortcut rows: drop the left-accent spine and give each
     card a bordered chevron-row treatment — icon on the left, title
     + description in the middle, ">" chevron pinned to the right.
     Reads as a "tap to open" list item, matching the mobile redesign
     mockup. Minimal gap between consecutive cards so the list reads
     as a tight set; section-header margin-bottom handles the larger
     separation between sections. */
  .ti-action-cards { gap: 0.35rem; }
  .shortcuts-sidebar .sidebar-shortcut.ti-action-card {
    padding: 0.95rem 2.2rem 1rem 0.95rem;
    gap: 0.3rem;
    background: #ffffff;
    border: 1px solid #e2e6ee;
    border-left: 1px solid #e2e6ee;
    border-radius: 10px;
    position: relative;
  }
  .shortcuts-sidebar .sidebar-shortcut.ti-action-card::after {
    content: '';
    position: absolute;
    right: 0.85rem;
    top: 50%;
    width: 8px;
    height: 8px;
    border-right: 1.5px solid #9aa3b3;
    border-top: 1.5px solid #9aa3b3;
    transform: translateY(-50%) rotate(45deg);
    pointer-events: none;
    transition: border-color 0.14s;
  }
  @media (hover: hover) { .shortcuts-sidebar .sidebar-shortcut.ti-action-card:hover::after {
    border-right-color: var(--ti-accent);
    border-top-color: var(--ti-accent);
  } }
  .shortcuts-sidebar .sidebar-shortcut.ti-action-card.is-multi-selected {
    background: color-mix(in srgb, var(--ti-accent) 7%, #ffffff);
    border-color: var(--ti-accent);
  }
  .ti-action-card-header { gap: 0.4rem; }
  .ti-action-card-icon { width: 18px; height: 18px; }
  .ti-action-card-icon-svg { width: 16px; height: 16px; }
  .shortcuts-sidebar .ti-action-card .ti-action-card-name { font-size: 0.88rem; }
  .ti-action-card-desc { font-size: 0.74rem; line-height: 1.4; }
}

/* Custom-search page — the panel takes the full page width. AI
   action cards use auto-fit grid with BOUNDED cell width
   (minmax(260px, 340px)) so cells respond to viewport width
   (more columns when wider) but never stretch past 340px when
   there's leftover row space. A row with one card sits at 340px
   on the left, not blown out across the full panel; a wide
   viewport gets 3–4 columns instead of 2 fat ones. The continuous-
   spine effect doesn't work in a multi-column grid (stubby orphan
   rules), so cells switch to a proper bordered tile treatment. */
/* Custom-search pages: use the same single-column tabular row
   layout as topic-page Topic Intelligence on mobile/tabular widths.
   Each row spans the full content width — icon + name on top, short
   description below, chevron on the right — instead of the 2-column
   tile grid we previously used at desktop widths. The user wants
   custom pages to read like the tabular nav on topic pages, not
   like a card deck. */
.topic-layout.is-custom .sidebar-shortcut.ti-action-card {
  padding: 0.7rem 0.95rem 0.75rem;
  background: #ffffff;
  border: 1px solid #e2e6ee;
  border-left: 1px solid #e2e6ee;
  border-radius: 8px;
}
@media (hover: hover) { .topic-layout.is-custom .sidebar-shortcut.ti-action-card:hover {
  background: #ffffff;
  border-color: var(--ti-accent);
} }
.topic-layout.is-custom .sidebar-shortcut.ti-action-card.is-multi-selected {
  background: color-mix(in srgb, var(--ti-accent) 6%, #ffffff);
  border-color: var(--ti-accent);
}
/* Three-column Web Sources grid for is-custom (matches mobile
   tabular feel — three chips per row, full-width tabular rather
   than the 4-col compact pack we had at desktop). */

/* === Submission bar ===
   Floats at the bottom of the Topic Intelligence panel once one or more
   shortcuts are selected. Reads clearly as the way to submit: a labelled
   header, a "Send to" model picker, and both a quick Submit and a full
   Review & Submit action. */
.shortcuts-multi-submit-wrap {
  flex-direction: column;
  align-items: stretch;
  gap: 0.6rem;
  padding: 0.8rem 0.85rem 0.85rem;
  background: #ffffff;
  border: 1px solid #ccd6e6;
  border-radius: 13px;
  box-shadow:
    0 2px 4px rgba(15, 26, 46, 0.05),
    0 10px 22px rgba(15, 26, 46, 0.15),
    0 24px 48px rgba(15, 26, 46, 0.12);
}
.shortcuts-multi-submit-wrap > * + * { border-top: none; }
.shortcuts-sidebar:has(.shortcuts-multi-submit-wrap.is-visible) .shortcuts-scroll-wrap { padding-bottom: 10.5rem; }

/* Head — title eyebrow, then count + Clear on one row */
.shortcuts-multi-head {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  min-width: 0;
}
.shortcuts-multi-eyebrow {
  font-family: var(--font-family);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-primary);
  line-height: 1;
}
.shortcuts-multi-headrow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
}
.shortcuts-multi-count-label {
  font-family: var(--font-family);
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: -0.008em;
  color: var(--color-text);
  white-space: nowrap;
}
.shortcuts-multi-clear {
  flex: 0 0 auto;
  background: none;
  border: none;
  color: var(--color-text-muted);
  font-family: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  cursor: pointer;
  padding: 0.2rem 0.35rem;
  border-radius: 6px;
  transition: color 0.12s, background 0.12s;
}
@media (hover: hover) { .shortcuts-multi-clear:hover { color: #b91c1c; background: #fbecec; } }
.shortcuts-multi-clear:disabled { color: var(--color-text-light); cursor: default; background: none; }

/* "Send to" model picker */
.shortcuts-multi-modelrow {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}
.shortcuts-multi-modellabel {
  flex: 0 0 auto;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--color-text-muted);
}
.shortcuts-multi-modelselect-wrap { position: relative; flex: 1 1 auto; min-width: 0; }
.shortcuts-multi-model {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  font-family: var(--font-family);
  font-size: 0.86rem;
  font-weight: 600;
  color: var(--color-primary);
  background: #f7f9fc;
  border: 1px solid #d7deea;
  border-radius: 8px;
  padding: 0.45rem 1.9rem 0.45rem 0.6rem;
  cursor: pointer;
  transition: border-color 0.12s, background 0.12s;
}
@media (hover: hover) { .shortcuts-multi-model:hover { border-color: #b9c4d6; } }
.shortcuts-multi-model:focus { outline: none; border-color: var(--color-primary-light); box-shadow: 0 0 0 3px rgba(58, 74, 99, 0.1); }
.shortcuts-multi-modelselect-chev {
  position: absolute;
  right: 0.6rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--color-text-muted);
  pointer-events: none;
}

/* Actions — equal-width pair: quiet Preview, then filled Submit. Equal
   flex-basis keeps either label from overflowing the bar. */
.shortcuts-multi-trigger-utils {
  display: flex;
  align-items: stretch;
  gap: 0.55rem;
}
.shortcuts-multi-review,
.shortcuts-multi-submit-direct {
  flex: 1 1 0;
  min-width: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  font-family: inherit;
  font-weight: 600;
  font-size: 0.92rem;
  letter-spacing: -0.005em;
  padding: 0.6rem 0.85rem;
  border-radius: 9px;
  cursor: pointer;
  white-space: nowrap;
}
.shortcuts-multi-review {
  background: #fff;
  color: var(--color-primary);
  border: 1px solid #cbd4e2;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
@media (hover: hover) { .shortcuts-multi-review:hover { background: var(--color-bg-light); border-color: var(--color-primary-light); } }
.shortcuts-multi-review:disabled { opacity: 0.5; cursor: default; }
.shortcuts-multi-submit-direct {
  background: var(--color-primary);
  color: #fff;
  border: 1px solid var(--color-primary);
  box-shadow: 0 1px 2px rgba(15, 26, 46, 0.18);
  transition: background 0.14s, transform 0.1s, box-shadow 0.14s;
}
@media (hover: hover) { .shortcuts-multi-submit-direct:hover { background: var(--color-primary-dark); box-shadow: 0 3px 8px rgba(15, 26, 46, 0.24); } }
.shortcuts-multi-submit-direct:active { transform: translateY(1px); }
.shortcuts-multi-submit-direct:disabled { opacity: 0.5; cursor: default; box-shadow: none; }
.shortcuts-multi-submit-direct svg { flex: 0 0 auto; }

/* Custom-search page bar is wider → keep the picker + actions inline. */
body.custom-mode .shortcuts-multi-submit-wrap { flex-direction: row; align-items: center; flex-wrap: wrap; gap: 0.7rem 0.9rem; }
body.custom-mode .shortcuts-multi-head { flex: 0 0 auto; }
body.custom-mode .shortcuts-multi-modelrow { flex: 1 1 220px; }
body.custom-mode .shortcuts-multi-trigger-utils { flex: 0 0 auto; }
body.custom-mode .shortcuts-multi-review,
body.custom-mode .shortcuts-multi-submit-direct { flex: 0 0 auto; }

/* === Trending Now card (homepage) ======================================
   Sidebar card above Topic Intelligence (desktop) / its own mobile tab.
   Title + separator mirror News Feed / Topic Intelligence; the list is a
   tight fixed-height scroll area with shared .scroll-fade indicators. */
/* The card fills its section (desktop row 2 below Topic Intelligence, or
   the mobile Trending tab); the list flexes to take the remaining height
   and scrolls — so how many entries show is driven by available space. */
/* Title — same treatment as .newsfeed-title / .sidebar-card-title: navy
   display type with a hairline separator below. */
/* Attribution + freshness — sit BELOW the separator, quiet. */

/* List — tight rows inside a fade-scrolled area that fills the card. */
.trending-list-wrap {
  position: relative;
  margin-top: 0.55rem;
  flex: 1 1 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.trending-list-wrap.has-overflow-top .scroll-fade-top { opacity: 1; }
.trending-list-wrap.has-overflow-bottom .scroll-fade-bottom { opacity: 1; }
.trending-list {
  list-style: none; margin: 0; padding: 0;
  display: flex; flex-direction: column; gap: 0;
}
.trending-row {
  display: flex; align-items: center; gap: 0.5rem; width: 100%;
  background: none; border: none; cursor: pointer; font-family: inherit; text-align: left;
  padding: 0.5rem 0.55rem; border-radius: 8px;
  color: var(--color-text);
  transition: background 0.12s, color 0.12s;
}
@media (hover: hover) { .trending-row:hover { background: var(--color-bg-light); color: var(--color-primary); } }
.trending-row:active { background: #eef1f6; }
.trending-row-text {
  flex: 1 1 auto; min-width: 0;
  font-size: 0.84rem; font-weight: 600; letter-spacing: -0.006em;
  /* Google Trends returns lowercase queries — capitalize each word so
     the list reads as proper trending headlines. */
  text-transform: capitalize;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.trending-row-chev { flex: 0 0 auto; color: var(--color-text-light); transition: transform 0.12s, color 0.12s; }
@media (hover: hover) { .trending-row:hover .trending-row-chev { color: var(--color-primary); transform: translateX(2px); } }

.trending-empty { font-size: 0.84rem; color: var(--color-text-muted); padding: 0.4rem 0.1rem; }
@keyframes trending-shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }

/* Mobile / tablet (own Trending tab): the active "Trending" tab pill
   already labels the panel, so the duplicate "Trending Now" title +
   separator are hidden here; the quiet "via Google Trends · Updated …"
   meta stays. The fill behaviour is handled by the base rules above. */
@media (max-width: 899.98px) {
  body.app-mode .topic-layout:not(.is-custom)  #section-trending .trending-title {
    display: none;
  }
  body.app-mode .topic-layout:not(.is-custom)  #section-trending .trending-meta {
    margin-top: 1.1rem;
  }
}


/* === Trending detail modal ===========================================
   Opened from a Trending Now row. Sits BELOW the prompt modal (z 200/201)
   so clicking a shortcut stacks Review & Submit on top. */
.td-overlay {
  position: fixed; inset: 0;
  background: rgba(15, 26, 46, 0.52);
  backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px);
  z-index: 150;
}
.td-panel {
  position: fixed; z-index: 151; top: 50%; left: 50%;
  width: min(600px, calc(100vw - 2rem)); max-height: min(88vh, 800px);
  display: flex; flex-direction: column; overflow: hidden;
  background: #fff; border: 1px solid rgba(15, 23, 42, 0.06); border-radius: 16px;
  box-shadow: 0 30px 70px -16px rgba(15, 23, 42, 0.40), 0 10px 22px -10px rgba(15, 23, 42, 0.20);
  transform: translate(-50%, -50%) scale(0.97); opacity: 0;
  transition: opacity 0.18s ease, transform 0.22s cubic-bezier(0.2, 0.9, 0.3, 1.05);
}
.td-panel.is-in { transform: translate(-50%, -50%) scale(1); opacity: 1; }

/* Header — title block with the close button + Google Trends link living
   up here, so the body is purely the related chips + the two sections. */
.td-header { position: relative; padding: 1.05rem 1.2rem 0.85rem; border-bottom: 1px solid var(--color-surface-border); flex-shrink: 0; }
.td-back { display: inline-flex; align-items: center; gap: 0.25rem; background: none; border: none; padding: 0 0 0.5rem; margin: 0; font-family: inherit; font-size: 0.74rem; font-weight: 600; color: var(--color-text-muted); cursor: pointer; transition: color 0.12s; }
.td-back svg { flex: 0 0 auto; }
@media (hover: hover) { .td-back:hover { color: var(--color-primary); } }
.td-eyebrow { display: block; font-family: var(--font-family); font-size: 0.64rem; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #e8590c; line-height: 1; }
.td-title { margin: 0.3rem 2rem 0 0; font-family: var(--font-display); font-size: 1.3rem; font-weight: 700; letter-spacing: -0.022em; color: var(--color-primary); line-height: 1.14; }
.td-headmeta { display: flex; align-items: baseline; flex-wrap: wrap; gap: 0.25rem 0.7rem; margin-top: 0.5rem; }
.td-sub { font-size: 0.76rem; font-weight: 500; color: var(--color-text-muted); }
.td-trends-link { display: inline-flex; align-items: center; gap: 0.2rem; font-size: 0.76rem; font-weight: 600; color: #2563eb; text-decoration: none; }
@media (hover: hover) { .td-trends-link:hover { text-decoration: underline; } }
.td-close { position: absolute; top: 0.85rem; right: 0.9rem; width: 34px; height: 34px; display: inline-flex; align-items: center; justify-content: center; background: #f1f3f7; border: 1px solid #e7eaf0; border-radius: 9px; color: var(--color-text-muted); cursor: pointer; transition: background 0.14s, color 0.14s; }
@media (hover: hover) { .td-close:hover { background: #e8ecf2; color: var(--color-text); } }
.td-close svg { width: 15px; height: 15px; display: block; }

.td-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 1rem 1.2rem 1.25rem; }

/* Related searches — clickable chips that drill into their own trend view */
.td-related { margin: 0 0 0.2rem; }
.td-related-label { display: block; font-size: 0.62rem; font-weight: 700; letter-spacing: 0.09em; text-transform: uppercase; color: var(--color-text-light); margin-bottom: 0.45rem; }
.td-related-chips { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.td-related-chip { max-width: 100%; font-family: inherit; font-size: 0.78rem; font-weight: 500; color: var(--color-text); background: #f4f6f9; border: 1px solid #e6eaf0; border-radius: 999px; padding: 0.3rem 0.7rem; cursor: pointer; transition: background 0.12s, border-color 0.12s, color 0.12s; text-transform: capitalize; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
@media (hover: hover) { .td-related-chip:hover { background: #eef1f6; border-color: #d7deea; color: var(--color-primary); } }

/* Sections — clear navy headers with a hairline divider above so "Trending
   101" / "Trending Intelligence" read as real section breaks, not afterthoughts. */
.td-section { padding-top: 1.15rem; margin-top: 1.15rem; border-top: 1px solid #eef0f4; }
.td-section:first-child { padding-top: 0; margin-top: 0; border-top: none; }
.td-section-label { font-family: var(--font-display); font-size: 0.98rem; font-weight: 700; letter-spacing: -0.012em; color: var(--color-primary); margin-bottom: 0.65rem; display: flex; align-items: center; gap: 7px; }
.td-section-label .ai-result-badge { font-size: 0.58rem; }
.td-ai-summary { margin: 0 0 9px; font-size: 0.94rem; font-weight: 600; line-height: 1.4; color: #1c3a6b; }
.td-ai-brief .ai-result-body { font-size: 0.875rem; line-height: 1.6; color: #2c3a52; white-space: normal; }
.td-ai-empty { margin: 0; font-size: 0.85rem; color: var(--color-text-muted); }

.td-shortcut-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 0.05rem; }
.td-shortcut { display: flex; align-items: center; gap: 0.65rem; width: 100%; text-align: left; background: none; border: none; cursor: pointer; padding: 0.45rem 0.5rem; border-radius: 8px; color: var(--color-text); font-family: inherit; transition: background 0.12s; }
@media (hover: hover) { .td-shortcut:hover { background: var(--color-bg-light); } }
.td-row-text { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 0.08rem; }
.td-row-name { font-size: 0.88rem; font-weight: 600; letter-spacing: -0.006em; }
.td-row-desc { font-size: 0.76rem; color: var(--color-text-muted); }
.td-row-chev { flex: 0 0 auto; color: var(--color-text-light); transition: color 0.12s, transform 0.12s; }
@media (hover: hover) { .td-shortcut:hover .td-row-chev { color: var(--color-primary); transform: translateX(2px); } }

/* Trending Intelligence accordions — a touch more compact than elsewhere on
   the site (thinner rows, slightly smaller icon/type). */
.td-section .ti-accordions { display: flex; flex-direction: column; gap: 0.4rem; }
.td-body .ti-accordion { border: 1px solid #ebedf2; border-radius: 10px; }
.td-body .ti-accordion-summary { padding: 0.5rem 0.7rem; column-gap: 0.4rem; row-gap: 0.18rem; }
.td-body .ti-accordion-icon { width: 17px; height: 17px; }
.td-body .ti-accordion-icon svg { width: 16px; height: 16px; }
.td-body .ti-accordion-title { font-size: 0.88rem; }
.td-body .ti-accordion-blurb { font-size: 0.7rem; line-height: 1.3; }
.td-body .ti-accordion-chev svg { width: 17px; height: 17px; }

@media (max-width: 640px) {
  .td-panel { width: calc(100vw - 1rem); max-height: 92vh; border-radius: 14px; }
  .td-body { padding: 0.9rem 1rem 1.1rem; }
}

/* === Global Trending modal (from the nav pill) =======================
   Reuses the Trending card (renderTrending) in a centered modal. Sits
   below the trending detail modal (z 150) so a clicked term stacks on
   top. */
/* Centered-card takeover (matches the Topics modal): never full-screen, the
   dimmed site stays visible around it. The panel is a separate fixed element
   (not a child of the overlay), so it self-centers via fixed positioning. */
.tlm-panel {
  position: fixed; z-index: 141; top: 50%; left: 50%;
  width: min(760px, calc(100% - 2rem)); height: min(86vh, 680px);
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--color-surface); border: 1px solid rgba(15, 23, 42, 0.06); border-radius: 16px;
  box-shadow: 0 30px 70px -16px rgba(15, 23, 42, 0.40), 0 10px 22px -10px rgba(15, 23, 42, 0.20);
  padding: 0;
  transform: translate(-50%, -50%) scale(0.97); opacity: 0;
  transition: opacity 0.18s ease, transform 0.22s cubic-bezier(0.2, 0.9, 0.3, 1.05);
}
.tlm-panel.is-in { transform: translate(-50%, -50%) scale(1); opacity: 1; }
/* Fixed centered header with a light separator; body scrolls under it. */
/* Sticky control bar in the modal header (#81): the legend block + category
   filter sit under the subtext, so they stay visible while the grid scrolls. */
.tlm-controlbar { margin-top: 0.85rem; }
.tlm-controlbar-inner { display: flex; align-items: center; justify-content: center; gap: 9px 14px; flex-wrap: wrap; }
/* The trending card renders its own left-aligned head — hide it; the centered
   .tlm-head above labels the modal. */
/* Match the search modal's close chip so it stands out (was a faint
   borderless circle). */
/* Scroll the modal body itself — the trend-card grid has no inner scroll
   container (the old .trending-scroll element is gone), so without this the
   list overflows the clipped panel with no way to scroll. */
/* Strip the sidebar-card chrome — the modal panel provides the surface. */
/* Size to content (the panel only has a max-height), and let the list grow
   to a capped height then scroll — the fill-to-flex behaviour needs a fixed
   parent height, which a content-sized modal doesn't provide. */
/* Leave room so the "Trending Now" title doesn't run under the close button. */
/* Two-column trending list on desktop (the takeover is wide enough now). */
@media (max-width: 640px) {
  /* Stay a centered card on mobile too (not full-screen) — site visible behind. */
  .tlm-panel { border-radius: 14px; }
}

/* === Shared takeover modal shell =====================================
   Full-screen on mobile, a large centered card (~960px) on desktop. Used
   by the Search modal; the Topics / Trends / Settings panels are sized to
   match. */
.takeover-overlay {
  position: fixed; inset: 0;
  background: rgba(15, 26, 46, 0.5);
  backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px);
  z-index: 160;
  display: flex; align-items: center; justify-content: center; padding: 1rem;
}
.takeover-panel {
  position: relative;
  width: 100%; max-width: 760px;
  max-height: 86vh;
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--color-surface); border: 1px solid rgba(15, 23, 42, 0.06); border-radius: 16px;
  box-shadow: 0 30px 80px -18px rgba(15, 23, 42, 0.42), 0 10px 24px -10px rgba(15, 23, 42, 0.2);
  transform: scale(0.98); opacity: 0;
  transition: opacity 0.16s ease, transform 0.2s cubic-bezier(0.2, 0.9, 0.3, 1.05);
}
.takeover-panel.is-in { transform: scale(1); opacity: 1; }
/* Mobile: a large, consistent screen takeover — small margins all around (some
   breathing room, dimmed site still peeks behind), NOT a tiny centered card. */
@media (max-width: 640px) {
  .takeover-overlay { padding: 0.7rem; }
  .takeover-panel { max-width: 100%; max-height: 94vh; border-radius: 16px; }
  .aii-modal-panel { height: 94vh; max-width: 100%; }
}

/* === AI Intelligence modal (#13) ===================================== */
/* A CONSISTENT, generous size — never resizes with content. Wider + taller than
   the base takeover so the picker/brief always have room. */
.aii-modal-panel { width: 100%; max-width: 760px; height: min(88vh, 820px); }
.aii-modal-head {
  position: relative; flex-shrink: 0; display: flex; align-items: center; gap: 0.6rem;
  padding: 0.85rem 1rem 0.85rem 1.1rem; border-bottom: 1px solid var(--color-surface-border);
}
.aii-modal-head-id { display: flex; align-items: center; gap: 0.5rem; min-width: 0; }
.aii-modal-logo { display: inline-flex; width: 23px; height: 23px; flex: none; align-items: center; justify-content: center; border-radius: 7px; background: var(--color-primary); color: #fff; }
/* Quiet modal brand — it's chrome; the topic title is the editorial hero below. */
.aii-modal-title { margin: 0; font-family: var(--font-display); font-size: 0.95rem; font-weight: 600; letter-spacing: -0.008em; color: var(--color-text-muted); white-space: nowrap; }
.aii-modal-head-right { margin-left: auto; display: flex; align-items: center; min-width: 0; }
/* Close is pinned to the top-right corner in BOTH chromes so it never shifts. */
.aii-modal-close { position: absolute; top: 0.7rem; right: 0.75rem; z-index: 2; flex: 0 0 auto; width: 34px; height: 34px; display: inline-flex; align-items: center; justify-content: center; background: #f1f3f7; border: 1px solid #e7eaf0; border-radius: 8px; color: var(--color-text-muted); cursor: pointer; transition: background .14s, color .14s; }
@media (hover: hover) { .aii-modal-close:hover { background: #e8ecf2; color: var(--color-text); } }

/* Intro chrome (Step 1 topic picker) — a centered title card like the Search /
   Trending modals; collapses to the compact corner identity once drilled in. */
.aii-modal-introhead { display: none; }
.aii-modal-panel:not(.is-intro) .aii-modal-introhead { display: none; }
.aii-modal-panel.is-intro .aii-modal-head-id { display: none; }
.aii-modal-panel.is-intro .aii-modal-head {
  flex-direction: column; align-items: center; text-align: center; gap: 0;
  padding: 1.4rem 2.6rem 0.75rem;
}
.aii-modal-panel.is-intro .aii-modal-introhead { display: flex; flex-direction: column; align-items: center; gap: 0.45rem; width: 100%; }
/* Logo sits to the LEFT of the title (one row), not stacked above it. */
.aii-modal-introtitlerow { display: inline-flex; align-items: center; gap: 0.6rem; }
.aii-modal-intrologo { display: inline-flex; width: 28px; height: 28px; flex: none; align-items: center; justify-content: center; border-radius: 8px; background: var(--color-primary); color: #fff; }
.aii-modal-intrologo svg { width: 15px; height: 15px; }
.aii-modal-introtitle { margin: 0; font-family: var(--font-display); font-size: 1.3rem; font-weight: 700; letter-spacing: -0.025em; color: var(--color-primary); }
.aii-modal-introsub { margin: 0; font-size: 0.88rem; line-height: 1.45; color: var(--color-text-muted); max-width: 46ch; }
/* Subtitle wraps to two lines (break after "term,") only when it would otherwise
   wrap awkwardly; stays one line where it fits. */
.aii-sub-break { display: none; }
@media (max-width: 560px) { .aii-sub-break { display: inline; } }
/* The picker's own in-body heading is now carried by the centered modal head. */
.aii-modal-body .aii-tp-head { display: none; }
/* With that heading gone, drop the picker's top padding so the search bar sits
   snug under the modal head (no orphan gap). */
.aii-modal-body .aii-tp { padding-top: 0; }
.aii-modal-chip { display: inline-flex; align-items: center; max-width: 46vw; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 0.32rem 0.75rem; background: color-mix(in srgb, var(--color-primary) 8%, #fff); border: 1px solid color-mix(in srgb, var(--color-primary) 20%, #fff); border-radius: 999px; font-size: 0.82rem; font-weight: 600; color: var(--color-primary); }
.aii-modal-topic { display: inline-flex; align-items: center; gap: 0.45rem; }
.aii-modal-topic-lead { font-size: 0.66rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.09em; color: var(--color-text-muted); }
.aii-modal-topic-wrap { position: relative; display: inline-flex; align-items: center; }
.aii-modal-topic-select { appearance: none; -webkit-appearance: none; padding: 0.36rem 1.7rem 0.36rem 0.7rem; border: 1px solid var(--color-surface-border); border-radius: 8px; background: #fff; font-family: inherit; font-size: 0.82rem; font-weight: 600; color: var(--color-text); cursor: pointer; }
.aii-modal-topic-wrap svg { position: absolute; right: 0.5rem; pointer-events: none; color: var(--color-text-muted); }
/* padding-top:0 so the content view's position:sticky head pins FLUSH to the top
   — any top padding leaves a thin strip where scrolled content creeps in above it. */
.aii-modal-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 0 1.1rem 0.6rem; }
/* The hosted component's own header duplicates the modal header — drop it, and
   let the flip-nav flow in the scrolling body (no fixed-height stage). */
.aii-modal-body .aii-head { display: none; }
.aii-modal-body .aii, .aii-modal-body .aii-stage { height: auto; overflow: visible; }
/* One cohesive surface: the component's own card frame (border + radius + white
   fill) nested inside the modal's white body reads as a card-within-a-card.
   Flatten it so the content sits flush in the modal; the modal body already
   provides the gutter, so the stage adds none. */
.aii-modal-body .aii { border: none; border-radius: 0; background: none; }
.aii-modal-body .aii-stage { padding: 0; }
/* Narrow screens: the title + topic picker can't share one row — keep the
   title and close on top, drop the picker to its own full-width row below. */
@media (max-width: 560px) {
  .aii-modal-head { flex-wrap: wrap; row-gap: 0.55rem; }
  .aii-modal-head-id { order: 1; }
  .aii-modal-close { order: 2; margin-left: auto; }
  .aii-modal-head-right { order: 3; flex-basis: 100%; margin-left: 0; }
  .aii-modal-topic { width: 100%; }
  .aii-modal-topic-wrap, .aii-modal-topic-select { flex: 1 1 auto; width: 100%; }
}

/* Mid-size screens (tablet / small laptop): below the 900px desktop breakpoint
   the phone rule caps every modal at 440px, which strands a lot of empty space
   here. Widen them to use the available width. Phones (≤640) keep the compact
   440 card — that size is deliberate. Source order + matching specificity (html-
   prefixed, like the phone rule) lets this win for the 641–899 band. */
@media (min-width: 641px) and (max-width: 899.98px) {
  html .takeover-panel,
  html .all-topics-modal-card,
  html .tlm-panel,
  html .td-panel,
  html .aii-modal-panel {
    max-width: 720px;
    width: calc(100% - 3rem);
  }
}

/* === Search modal (Custom Topic Search reborn) ======================= */
.search-page-panel { background: var(--color-surface); }

/* Empty hero state */
.search-page-close-float { position: absolute; top: 0.85rem; right: 0.85rem; z-index: 2; }
.search-page-hero {
  flex: 1 1 auto; min-height: 0;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  text-align: center; gap: 0.85rem; padding: 2.5rem 1.5rem 3rem;
}
.search-page-hero-title {
  margin: 0; font-family: var(--font-display);
  font-size: clamp(1.5rem, 3.2vw, 2.15rem); font-weight: 700; line-height: 1.12;
  letter-spacing: -0.025em; color: var(--color-primary);
}
.search-page-hero-sub {
  margin: 0; max-width: 30rem; color: var(--color-text-muted);
  font-size: 1rem; line-height: 1.5;
}
.search-page-form--hero { width: min(34rem, 100%); margin-top: 0.6rem; }

/* Shared form (hero + top bar) */
.search-page-form { position: relative; display: flex; align-items: center; }
.search-page-input-icon {
  position: absolute; left: 0.95rem; top: 50%; transform: translateY(-50%);
  display: inline-flex; width: 18px; height: 18px; color: var(--color-text-muted); pointer-events: none;
}
.search-page-form--hero .search-page-input-icon { width: 20px; height: 20px; left: 1.1rem; }
.search-page-input-icon svg { width: 100%; height: 100%; display: block; }
.search-page-input {
  width: 100%; box-sizing: border-box;
  height: 52px; padding: 0 2.9rem 0 3rem;
  border: 1.5px solid #e2e6ee; border-radius: 999px; background: #f7f9fc;
  font-family: inherit; font-size: 1.05rem; color: var(--color-text);
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
}
.search-page-input::placeholder { color: #9aa3b2; }
.search-page-input:focus {
  outline: none; border-color: var(--color-accent, #f97316); background: #fff;
  box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.12);
}
.search-page-form--top { flex: 1 1 auto; }
.search-page-form--top .search-page-input { height: 44px; font-size: 0.98rem; padding-left: 2.7rem; }
.search-page-input-icon { z-index: 1; }
.search-page-form--top .search-page-input-icon { left: 0.85rem; }
.search-page-clear {
  position: absolute; right: 0.5rem; top: 50%; transform: translateY(-50%);
  width: 28px; height: 28px; display: inline-flex; align-items: center; justify-content: center;
  background: #eceff4; border: none; border-radius: 50%; color: var(--color-text-muted); cursor: pointer;
  transition: background 0.14s, color 0.14s;
}
@media (hover: hover) { .search-page-clear:hover { background: #e0e4ec; color: var(--color-text); } }
.search-page-clear svg { width: 13px; height: 13px; display: block; }

/* Filled state: head holds the search bar + close; body holds the results */
.search-page-head { gap: 0.6rem; }
.search-page-body { padding-top: 0.9rem; }
.search-page-results .shortcuts-sidebar {
  border: none; box-shadow: none; padding: 0; margin: 0; background: transparent; max-width: none;
}
/* Single-column, full-width accordion layout (no 2-col grid). */
.search-page-results .ti-accordions { display: grid; grid-template-columns: 1fr; gap: 0.6rem; }
/* The multi-select submit bar is absolute-anchored to the sidebar bottom,
   which strands it at the foot of the (tall) scrolled content. Inside the
   modal, float it as a centered fixed action bar (same pattern the old
   custom page used). Mobile (<900px) already pins it via the existing
   fixed rule. */
@media (min-width: 900px) {
  .search-page-results .shortcuts-multi-submit-wrap {
    position: fixed; left: 0; right: 0; bottom: 1.6rem;
    width: min(520px, calc(100vw - 3rem)); margin-left: auto; margin-right: auto;
    z-index: 170;
    box-shadow: 0 12px 30px rgba(15, 26, 46, 0.18), 0 2px 6px rgba(15, 26, 46, 0.08);
  }
  .search-page-results .shortcuts-multi-submit-wrap::before { display: none; }
  .search-page-results .shortcuts-sidebar:has(.shortcuts-multi-submit-wrap.is-visible) .shortcuts-scroll-wrap { padding-bottom: 0; }
}

/* === Expanding search panel (homepage hero + nav modal) ============== */
.search-panel { position: relative; display: flex; flex-direction: column; width: 100%; }
/* Modal close lives in the panel's top-right corner (a standard modal X),
   separate from the search bar's inline actions so they never overlap. */
.search-panel-corner-close {
  position: absolute; top: 0.6rem; right: 0.7rem; z-index: 4;
  width: 34px; height: 34px; display: inline-flex; align-items: center; justify-content: center;
  background: #f1f3f7; border: 1px solid #e7eaf0; border-radius: 9px;
  color: var(--color-text-muted); cursor: pointer; transition: background 0.14s, color 0.14s;
}
@media (hover: hover) { .search-panel-corner-close:hover { background: #e8ecf2; color: var(--color-text); } }
.search-panel-corner-close svg { width: 15px; height: 15px; display: block; }

/* Hero (headline + subtext) — collapses on expand. */
.search-panel-hero {
  display: grid; grid-template-rows: 1fr; opacity: 1;
  text-align: center; transition: grid-template-rows 0.32s ease, opacity 0.24s ease, margin 0.32s ease;
}
.search-panel-hero > * { overflow: hidden; min-height: 0; }
.search-panel-hero-inner { padding: 0.4rem 1rem 0.7rem; }
.search-panel-title { margin: 0 0 0.4rem; font-family: var(--font-display); font-size: clamp(1.1rem, 1.9vw, 1.35rem); font-weight: 700; line-height: 1.14; letter-spacing: -0.025em; color: var(--color-primary); }
.search-panel-sub { margin: 0 auto; max-width: 44rem; color: var(--color-text-muted); font-size: 0.88rem; line-height: 1.45; text-wrap: balance; }
/* Search modal subtitle — the "News, Resources and AI Knowledge." tagline sits
   under the "Search" header at a lighter weight than the homepage title. */
/* Let the tagline sit on one line where it fits and wrap naturally only when
   the viewport forces it — no balanced/forced mid-phrase break. */
.search-panel-tagline { margin: 0.1rem auto 0; max-width: 40rem; font-family: var(--font-display); font-size: 1rem; font-weight: 450; letter-spacing: -0.012em; color: #6b7689; }
@media (max-width: 560px) { .search-panel-tagline { font-size: 0.9rem; max-width: 26rem; } }
/* Centered modal search header (#img104): everything centers over the bar. */
.search-panel--modal .search-panel-hero-inner { text-align: center; }
/* Modal tagline — a touch bigger than the base, still the primary descriptor. */
.search-panel--modal .search-panel-tagline { font-weight: 550; color: #475569; font-size: 1.08rem; }
/* The "Type a topic…" hint now lives under the tagline, above the input. */
.search-panel-herohint { margin: 7px 0 0; max-width: 46rem; font-size: 0.9rem; line-height: 1.5; color: var(--color-text-muted); }
@media (max-width: 640px) {
  .search-panel--modal .search-panel-tagline { font-size: 1rem; font-weight: 550; }
  .search-panel-herohint { font-size: 0.85rem; }
}
/* Compact the homepage hero further on phones — it was eating too much of the
   first screen. */
@media (max-width: 640px) {
  /* Tighter top (was leaving a big gap above the title) + a calmer tagline. */
  .search-panel--inline .search-panel-hero-inner { padding: 0.45rem 0.9rem 0.55rem; }
  .search-panel--inline .search-panel-title { font-size: 1.14rem; margin-bottom: 0.3rem; }
  .search-panel--inline .search-panel-sub { font-size: 0.85rem; line-height: 1.45; }
}
/* Hero (tagline + subtext) stays visible AND fixed when expanded — the
   results reveal below it without the search bar sliding up toward the
   subtext (so no jump). Padding-bottom intentionally NOT shrunk here. */

/* Search bar row + suggestions dropdown. */
.search-panel-barrow { position: relative; padding: 0 0.2rem; }
.search-panel-form { position: relative; display: flex; align-items: center; }
.search-panel-icon { position: absolute; left: 0.65rem; top: 50%; transform: translateY(-50%); display: grid; place-items: center; width: 34px; height: 34px; border: none; background: none; border-radius: 9px; color: var(--color-text-muted); cursor: pointer; padding: 0; z-index: 2; transition: background .12s, color .12s; }
/* Fixed 19px glyph — the old `width:100%` rule below let the SVG fill the 34px
   button, ballooning the magnifier on the search page (#img342). */
.search-panel-icon svg { width: 19px !important; height: 19px !important; display: block; }
@media (hover: hover) { .search-panel-icon:hover { background: #eef2f8; color: #1d4ed8; } }
.search-panel-icon:active { background: #e5ebf5; }
.search-panel-input {
  width: 100%; box-sizing: border-box; height: 46px; padding: 0 3rem 0 3rem;
  border: 1.5px solid #e2e6ee; border-radius: 999px; background: #fff;
  font-family: inherit; font-size: 0.98rem; font-weight: 600; color: var(--color-text);
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
}
/* The placeholder stays regular-weight; only what the user types is bold (#140). */
.search-panel-input::placeholder { font-weight: 400; }
@media (max-width: 640px) {
  .search-panel--inline .search-panel-input { height: 46px; font-size: 0.98rem; }
}
.search-panel-input::placeholder { color: #9aa3b2; }
.search-panel-input:focus { outline: none; border-color: var(--color-accent, #f97316); background: #fff; box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.12); }
.search-panel-clear { position: absolute; right: 0.55rem; top: 50%; transform: translateY(-50%); width: 28px; height: 28px; display: inline-flex; align-items: center; justify-content: center; background: #eceff4; border: none; border-radius: 50%; color: var(--color-text-muted); cursor: pointer; }
@media (hover: hover) { .search-panel-clear:hover { background: #e0e4ec; color: var(--color-text); } }
.search-panel-clear[hidden] { display: none; }
.search-panel-clear svg { width: 13px; height: 13px; display: block; }
/* Copy-link icon in the search bar (modal only) — sits at the right, shifting
   left of the clear X when that's visible. Copies a deep link to the search. */
.search-panel-copylink { display: none; position: absolute; right: 0.55rem; top: 50%; transform: translateY(-50%); width: 28px; height: 28px; align-items: center; justify-content: center; background: #eceff4; border: none; border-radius: 50%; color: var(--color-text-muted); cursor: pointer; transition: background .14s, color .14s; z-index: 2; }
.search-panel--modal .search-panel-copylink { display: inline-flex; }
@media (hover: hover) { .search-panel-copylink:hover { background: #e0e4ec; color: var(--color-text); } }
.search-panel-copylink svg { width: 14px; height: 14px; display: block; }
.search-panel-copylink.is-copied { background: #f0fdf4; color: #15803d; }
.search-panel--modal .search-panel-form:has(.search-panel-clear:not([hidden])) .search-panel-copylink { right: 2.7rem; }
.search-panel--modal .search-panel-form:has(.search-panel-clear:not([hidden])) .search-panel-input { padding-right: 4.6rem; }
/* Input keeps its 52px height + 1.05rem text when expanded — don't shrink
   it, so the bar doesn't visibly resize the moment a search is entered. */

/* Suggestions dropdown. */
.search-panel-suggest {
  position: absolute; left: 0; right: 0; top: 100%; z-index: 30;
  background: #fff; border: 1.5px solid #d7e0ef; border-top: none;
  border-radius: 0 0 16px 16px; overflow: hidden; padding: 6px;
  box-shadow: 0 22px 40px -20px rgba(15, 23, 42, 0.26);
  transform-origin: top center; animation: spSuggestIn .2s cubic-bezier(.22,.61,.21,1);
}
@keyframes spSuggestIn { from { opacity: 0; transform: translateY(-8px) scaleY(0.96); } to { opacity: 1; transform: none; } }
.search-panel-suggest[hidden] { display: none; }
/* The input reads as the head of the dropdown: flat bottom corners + one calm,
   neutral border (no blue "active" focus ring or glow) so the two form ONE clean
   connected element while suggestions are open (#img364-366/370). */
.search-panel-barrow:has(.search-panel-suggest:not([hidden])) .search-panel-input,
.search-panel-barrow:has(.search-panel-suggest:not([hidden])) .search-panel-input:focus {
  border-radius: 14px 14px 0 0; border-color: #d7e0ef; border-width: 1.5px; border-bottom-color: #eef1f6;
  box-shadow: none;
}
.home-search-hero .search-panel-barrow:has(.search-panel-suggest:not([hidden])) .search-panel-input,
.home-search-hero .search-panel-barrow:has(.search-panel-suggest:not([hidden])) .search-panel-input:focus {
  border-radius: 14px 14px 0 0; border-color: #d7e0ef; border-bottom-color: #eef1f6; box-shadow: none;
}
/* Drop the bar's bottom padding while the dropdown is open so the panel butts
   directly against the input — no floating gap between them (#img364-366). */
.search-panel-barrow:has(.search-panel-suggest:not([hidden])) { padding-bottom: 0; }
.search-panel-suggest-row { display: flex; align-items: baseline; gap: 0.5rem; width: 100%; text-align: left; padding: 0.55rem 0.7rem; background: none; border: none; border-radius: 8px; cursor: pointer; font-family: inherit; color: var(--color-text); }
.search-panel-suggest-row.is-active { background: #f1f4f9; }
@media (hover: hover) { .search-panel-suggest-row:hover { background: #f1f4f9; } }
.search-panel-suggest-name { font-size: 0.94rem; font-weight: 500; color: #33415c; }
.search-panel-suggest-parent { font-size: 0.8rem; color: var(--color-text-muted); }
.search-panel-suggest-row.is-custom .search-panel-suggest-name { font-weight: 600; color: var(--color-primary); }
/* Trending typeahead rows (#77): a hot-trend glyph on the left + a "Trending ·
   Category" tag pushed to the right, so live searches read distinctly from
   topic matches. */
.search-panel-suggest-row.is-trend { align-items: center; }
.search-panel-suggest-ic { display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; flex: none; border-radius: 7px; background: color-mix(in srgb, var(--color-primary) 8%, #fff); color: var(--color-primary); }
.search-panel-suggest-ic svg { width: 13px; height: 13px; }
.search-panel-suggest-row.is-trend .search-panel-suggest-name { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.search-panel-suggest-tag { margin-left: auto; flex: none; font-size: 0.66rem; font-weight: 700; letter-spacing: 0.04em; text-transform: uppercase; color: #1f8f6b; background: color-mix(in srgb, #22a47a 11%, transparent); padding: 2px 8px; border-radius: 999px; white-space: nowrap; }
/* Topic typeahead rows: same icon-chip + name + right-pill shape as the trend
   rows, but the type pill is a neutral GREY "Topic" (vs the green Trending). The
   topic's own glyph sits in the left chip (matches the trend chip styling). */
.search-panel-suggest-row.is-topic { align-items: center; }
.search-panel-suggest-row.is-topic .search-panel-suggest-name { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.search-panel-suggest-tag--topic { color: var(--color-text-muted); background: color-mix(in srgb, var(--color-text-muted) 14%, transparent); }
/* Custom "search this term" — a distinct ACTION at the foot of the list: a hairline
   divider sets it off from the results above, a primary search chip + arrow read it
   as "run a full search," not another result row. */
.search-panel-suggest-row.is-custom { align-items: center; margin-top: 4px; padding: 0.6rem 0.7rem 0.6rem 2.6rem; border-top: 1px solid #eef1f6; border-radius: 8px; }
/* When "Search <term>" is the only/first row (no typeahead results above it) the
   divider + top margin drew a stray line above the preview text — drop them so it
   sits clean right under the input (#img366). */
.search-panel-suggest-row.is-custom:first-child { margin-top: 0; border-top: none; }
.search-panel-suggest-row.is-custom.is-active { background: color-mix(in srgb, var(--color-primary) 7%, #fff); }
@media (hover: hover) { .search-panel-suggest-row.is-custom:hover { background: color-mix(in srgb, var(--color-primary) 7%, #fff); } }
.search-panel-suggest-row.is-custom .search-panel-suggest-name { flex: 0 1 auto; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* Faint "Search" submit pill on the custom row — appears on hover/active. */
.search-panel-suggest-submit {
  margin-left: auto; flex: none; display: inline-flex; align-items: center; gap: 5px;
  padding: 4px 11px; border-radius: 999px; background: #eef2f8; color: #33517f;
  font-family: var(--font-family); font-size: 0.76rem; font-weight: 650;
  opacity: 0; transform: translateX(-2px); transition: opacity .14s ease, transform .14s ease, background .12s;
}
.search-panel-suggest-submit svg { flex: none; }
/* Differentiated from the typed input text — lighter weight + muted colour so it
   reads as a suggested action, not a duplicate of what you typed (#img370). */
.search-panel-suggest-row.is-custom .search-panel-suggest-name { color: #6b7a93; font-weight: 500; font-size: 0.9rem; }
.search-panel-suggest-row.is-custom.is-active .search-panel-suggest-submit,
.search-panel-suggest-row.is-custom:hover .search-panel-suggest-submit { opacity: 1; transform: none; }
.search-panel-suggest-row.is-custom:hover .search-panel-suggest-submit { background: #26375a; color: #fff; }

/* Tighten the home subnav "Featured │" separator → first-topic gap — there was
   too much air between the divider and "World" (#254). */

/* Tools (copy link) — shown only in expanded state. */
.search-panel-tools { display: flex; align-items: center; gap: 0.6rem; padding: 0.7rem 0.4rem 0.2rem; }
.search-panel-tools[hidden] { display: none; }
/* Copy link sits next to the close X — both are 36px tall with a 9px
   radius so they read as one matched control set (was a short pill beside
   a taller square). */
.search-panel-copy { display: inline-flex; align-items: center; gap: 0.4rem; height: 36px; box-sizing: border-box; background: #f1f4f9; border: 1px solid #e2e6ee; border-radius: 9px; padding: 0 0.75rem; font-family: inherit; font-size: 0.85rem; color: var(--color-text-muted); cursor: pointer; transition: background 0.14s, color 0.14s; }
@media (hover: hover) { .search-panel-copy:hover { background: #e8edf4; color: var(--color-text); } }
.search-panel-copy svg { width: 14px; height: 14px; display: block; }
.search-panel-copy.is-copied { color: #15803d; border-color: #bbf7d0; background: #f0fdf4; }

/* Results host — reveals via grid-rows. */
.search-panel-results { display: grid; grid-template-rows: 0fr; opacity: 0; transition: grid-template-rows 0.35s ease, opacity 0.3s ease; }
.search-panel-results > * { overflow: hidden; min-height: 0; }
.search-panel[data-state="expanded"] .search-panel-results { grid-template-rows: 1fr; opacity: 1; }
/* (The old empty-state Trending/Featured sections are gone — the empty search
   modal is now just the centered hero + bar, #img103.) */
/* Inset the results block by the same 0.2rem the .search-panel-barrow
   carries, so the "Search Intelligence" header (and accordions) line up
   with the search bar's left edge instead of sitting 0.2rem outside it. */
.search-panel-results .shortcuts-sidebar { border: none; box-shadow: none; padding: 0 0.2rem; margin: 0; background: transparent; max-width: none; }
/* Full-width, single-column paths in the search modal (no 2-col grid). */
.search-panel-results .ti-accordions { display: grid; grid-template-columns: 1fr; gap: 0.6rem; padding-top: 0.9rem; }

/* Search panel inside the takeover modal: pad the card. Collapsed = overflow
   visible so the suggestions dropdown can escape the short card; expanded =
   scroll the tall accordions within the card's max-height. */
/* Fixed-size modal (matches Topics / Trends). Sticky head (title + tagline)
   with a light separator; the search bar stays fixed; results scroll under. */
.search-page-panel.takeover-panel { overflow: hidden; padding: 0; height: min(86vh, 680px); }
.search-panel--modal { min-height: 0; display: flex; flex-direction: column; height: 100%; }
/* Top fold (#img103/104 redesign): NO grey band, no content sections below — the
   empty search dropdown is just the hero (title/tagline/hint) + bar, CENTERED in the
   viewport below the nav. Entering a term compresses the stage's animated paddings,
   gliding the whole block to the top while results fade in beneath — the padding
   values are the animation (flex centering isn't animatable, padding is). */
.search-panel--modal .search-panel-topfold {
  flex: 0 0 auto;
  /* Pinned while results scroll beneath (opaque white cover, full-bleed). Real
     air between the main nav and the "Search" header in the pushed-up state
     (#img124 — it was hugging the nav at 14px). */
  position: sticky; top: 0; z-index: 3;
  margin: 0 -2rem;
  padding: 30px 2rem 10px;
  background: #fff;
  display: flex; flex-direction: column; align-items: center;
  transition: padding 0.55s cubic-bezier(0.22, 0.61, 0.21, 1);
}
/* Collapsed (no term yet): center the hero in the space below the nav. The dropdown
   inner already spans the full viewport height; the top padding walks the content to
   ~vertical center (hero+bar ≈ 300px tall → half ≈ 150px). */
.search-panel--modal[data-state="collapsed"] .search-panel-topfold {
  padding-top: max(44px, calc(50dvh - var(--nav-h, 60px) / 2 - 165px));
  padding-bottom: 60px;
}
/* Hairline under the pinned bar once results are scrolling beneath it. */
.search-panel--modal[data-state="expanded"] .search-panel-topfold { border-bottom: 1px solid #eef1f6; }
.aii-nav-dd-search .aii-nav-dd-scroll { overflow-x: clip; overflow-clip-margin: 1500px; }
.aii-nav-dd-search .aii-nav-dd-inner { padding-left: 0; padding-right: 0; padding-top: 0; position: relative; }
.aii-nav-dd-search .aii-nav-dd-scroll { padding-left: 0; padding-right: 0; }
.aii-nav-dd-search .search-navdd-host { padding-left: 2rem; padding-right: 2rem; }
@media (max-width: 640px) {
  .aii-nav-dd-search .search-navdd-host { padding-left: 1rem; padding-right: 1rem; }
  .search-panel--modal .search-panel-topfold { margin: 0 -1rem; padding-left: 1rem; padding-right: 1rem; }
}
.search-panel--modal .search-panel-hero { flex-shrink: 0; }
/* Search bar sits in the fixed top section; a full-width divider beneath it
   separates the bar from the scrolling results (bar above the line, results
   below). */
/* No line under the search bar — the Jump-to nav's full-width bar is the only
   separator between the search area and the results. */
.search-panel--modal .search-panel-barrow { flex-shrink: 0; padding: 0.55rem 2px 0.5rem; border-bottom: none; }
/* The hero + bar cap to a comfortable centered column (#img104). */
.search-panel--modal .search-panel-hero,
.search-panel--modal .search-panel-barrow { width: 100%; max-width: 760px; align-self: center; box-sizing: border-box; }
.search-panel--modal .search-panel-results { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 0 2px 1.2rem; }
.search-panel--modal[data-state="collapsed"] .search-panel-results { display: none; }
/* Results glide in as the stage compresses upward. */
.search-panel--modal[data-state="expanded"] .search-panel-results-inner {
  animation: spResultsIn 0.45s cubic-bezier(0.22, 0.61, 0.21, 1) 0.12s both;
}
@keyframes spResultsIn { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
.search-panel--modal .search-panel-close { top: 0.5rem; right: 0.5rem; }
.search-panel--modal .search-panel-hero-inner { padding: 0 2.4rem 0.65rem; }
/* Search results: separate the Web Sources card from AI Intelligence above it,
   and pull its accordions up under the divider (they were stranded ~32px below). */
.search-panel-results-inner .websources-section { margin-top: 1.6rem; }
.search-panel-results-inner .websources-section .sidebar-card-header { margin-bottom: 0; padding-bottom: 0.5rem; }
.search-panel-results-inner .websources-section .ti-accordions-websources { margin-top: 0; padding-top: 0.7rem; }
/* Big centered "Search" header when idle; eases down to a compact header once a
   term is in and results own the screen. */
.search-panel--modal .search-panel-title {
  font-size: 1.5rem; margin-bottom: 0.35rem;
  transition: font-size 0.5s cubic-bezier(0.22, 0.61, 0.21, 1);
}
.search-panel--modal[data-state="collapsed"] .search-panel-title {
  font-size: clamp(1.8rem, 1.3rem + 1.8vw, 2.3rem);
}
/* Tagline + hint melt away once results take over (the compact header is just
   title + bar) — animated so the hand-off reads as one motion. */
.search-panel--modal .search-panel-tagline,
.search-panel--modal .search-panel-herohint {
  max-height: 90px;
  transition: opacity 0.3s ease, max-height 0.45s cubic-bezier(0.22, 0.61, 0.21, 1), margin 0.45s cubic-bezier(0.22, 0.61, 0.21, 1);
}
/* Balanced line breaks so the hint never strands a word ("...and AI / insights."),
   capped narrower so two lines split evenly (#img122). */
.search-panel--modal .search-panel-herohint { margin-left: auto; margin-right: auto; max-width: 34rem; text-wrap: balance; }
.search-panel--modal[data-state="expanded"] .search-panel-tagline,
.search-panel--modal[data-state="expanded"] .search-panel-herohint {
  opacity: 0; max-height: 0; margin-top: 0; margin-bottom: 0; overflow: hidden;
}

/* === Homepage inline search hero ===================================== */
/* Home keeps the app-mode grid placement but unlocks the viewport lock so
   the search hero sits on top and the whole page scrolls. */
html:has(body.home-search), body.home-search { overflow: visible; height: auto; }
body.home-search.app-mode #content,
body.home-search.app-mode.sticky-always.has-subnav #content {
  position: static; height: auto; min-height: 0; overflow: visible;
  /* The subnav is HIDDEN until scrolled past the quicklinks (#img193), so the hero
     only clears the nav itself — but it MUST clear it: the nav is fixed, so
     anything less than var(--nav-h) slides the title underneath it. */
  padding: calc(var(--nav-h) + 2.4rem) 0 3rem;
}
/* One cohesive centered width for the whole homepage — matches the main nav
   (var(--max-width) + 2rem padding) so the body content lines up with the nav
   instead of sitting ~80px narrower per side on wide screens. */
body.home-search.app-mode .topic-layout {
  height: auto; max-width: var(--max-width); margin: 0 auto; padding: 0 2rem 2rem;
}
/* Search hero + Trending live inside the full-width #section-searchtrends
   (one tab on mobile). They fill the section — strip their own max-width /
   side padding so they don't double-inset within the padded layout. */
#section-searchtrends { display: block; }
/* Home search hero is a contained CARD on the warm surface, sized to EXACTLY
   the search modal's width (.takeover-panel max-width: 600px) so clicking it
   lifts cleanly into the modal — same width, same color, no jump. The home
   inline search never expands in place (submit routes to the modal), so the
   600px cap constrains nothing but the resting title + bar. */
/* Homepage hero — a spacey gradient "command card": a large display title over a
   warm, elevated search bar. Fills the main column (no 600px cap now). */
/* Hero sits DIRECTLY on the off-white page — no card box (#img153/154). Faint
   knowledge icons wash the right side of the search zone (#img231): static,
   ultra-light, behind everything. */
.home-search-hero::before { content: none; }
@media (max-width: 900px) { .home-search-hero::before { width: min(200px, 42%); height: 150px; opacity: 0.5; } }
@media (max-width: 560px) { .home-search-hero::before { display: block; width: 130px; height: 110px; opacity: 0.28; top: 3.4rem; transform: none; } }
.home-search-hero {
  /* NB: no overflow:hidden — the typeahead dropdown is absolutely positioned and
     must be allowed to spill past the hero's bottom edge (#77). */
  position: relative;
  z-index: 20;
  max-width: 1080px; margin: 0 auto;
  padding: 0.6rem 0 0;
  background: none;
  border: none;
  border-radius: 0;
  box-shadow: none;
}
.home-search-hero::after { content: none; }
/* Decorative connected-lines art (#img154): dashed paths linking floating icon
   badges — trends (purple), AI (green), news (amber). Pure decoration. */
/* Fully static (#img223) — the constellation reads as a diagram, not a toy. */
.home-search-hero .search-panel { position: relative; z-index: 1; }
/* Balanced hero spacing (#75): a tight title→tagline gap and a deliberate,
   equal-ish tagline→search-bar gap (was unbalanced — 16px above, 0 below). */
.home-search-hero .search-panel-hero-inner { padding: 0.15rem 0 1rem; text-align: center; }
.home-search-hero .search-panel-title {
  text-align: center; max-width: none; white-space: nowrap;
  font-size: clamp(1.15rem, 0.8rem + 1.15vw, 1.5rem); line-height: 1.15; letter-spacing: -0.022em;
  margin: 0 auto 0.7rem;
}
/* Tagline sits centered between the headline and the bar; a touch more air below
   the bar too (#430). */
.home-search-hero .search-panel-tagline { margin-top: 0; line-height: 1.35; }
.home-search-hero .search-panel-barrow { padding: 0 0 0.3rem; }
/* On larger screens the tagline→search-bar gap read as far too airy — tighten it
   (mobile keeps its own spacing) (#img516). */
@media (min-width: 700px) {
  .home-search-hero .search-panel-hero-inner { padding-bottom: 0.2rem; }
}
/* Warm, elevated bar — rounded rect (not a pill), soft shadow, larger tap area. */
.home-search-hero .search-panel-input {
  height: 56px; border-radius: 14px; border: 1px solid #d7e0ef;
  padding: 0 3rem 0 3.15rem; font-size: 1.04rem;
  box-shadow: 0 10px 26px -14px rgba(31, 49, 99, 0.34);
}
.home-search-hero .search-panel-input:focus { border-color: #9db6e6; box-shadow: 0 10px 26px -14px rgba(31, 49, 99, 0.34), 0 0 0 4px rgba(80, 120, 210, 0.14); }
.home-search-hero .search-panel-icon { left: 0.6rem; color: #7a89a6; }
.home-search-hero .search-panel-icon svg { width: 20px; height: 20px; }
@media (hover: hover) { .home-search-hero .search-panel-icon:hover { background: #eef2f8; color: #1d4ed8; } }
/* No copy-link button cluttering the resting hero bar. */
.home-search-hero .search-panel[data-state="collapsed"] .search-panel-copylink { display: none; }
.home-search-hero .search-panel-results { max-width: 100%; }
/* Popular-topic starter chips under the home search bar — makes the card an
   actionable launchpad rather than an empty box. Hidden once a search expands. */
/* Starter launchpad under the home search bar — two clean labelled groups:
   Popular topics (link to the topic) + Trending now (run the search). */
.search-panel-starters { display: flex; flex-direction: column; gap: 15px; margin-top: 20px; text-align: left; }
.sp-starter-group { display: flex; flex-direction: column; gap: 9px; }
.sp-starter-label { font-size: 0.68rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: #98a2b6; }
.sp-starter-chips { display: flex; flex-wrap: wrap; gap: 7px; }
.sp-chip { display: inline-flex; align-items: center; gap: 6px; padding: 6px 13px; border-radius: 999px; border: 1px solid #dde3ee; background: #fff; color: #34405a; font-family: var(--font-family); font-size: 0.8rem; font-weight: 600; line-height: 1; text-decoration: none; cursor: pointer; transition: border-color .14s, color .14s, background .14s; }
@media (hover: hover) { .sp-chip:hover { border-color: #2f6df0; color: #1d4ed8; background: #f4f7ff; } }
.sp-chip--trend svg { width: 13px; height: 13px; flex: none; color: #2f6df0; }
.search-panel--inline[data-state="expanded"] .search-panel-starters { display: none; }
/* The home search card no longer shows the topic/trend chips at ANY size. */
body.home-search .home-search-hero .search-panel-starters { display: none; }
@media (max-width: 640px) {
  .home-search-hero { padding: 0.9rem 0 0; }
  .home-search-hero .search-panel-hero-inner { text-align: center; }
  .home-search-hero .search-panel-title { font-size: clamp(1.45rem, 6.4vw, 1.8rem); text-align: center; }
  .home-search-hero .search-panel-input { height: 48px; font-size: 0.98rem; }
}
/* The bar fills the card (minus padding), matching how it fills the 600px
   modal — so the bar width is identical in card and modal. */
@media (min-width: 720px) {
  .search-panel--inline[data-state="collapsed"] .search-panel-barrow,
  .search-panel--inline[data-state="expanded"] .search-panel-barrow { width: 100%; max-width: none; margin-left: 0; margin-right: 0; }
}
/* === Homepage dashboard layout (2026-06-10 redesign) ====================
   Two columns on desktop (≥1024px): a MAIN column (Search card → AI
   Intelligence → News Feed) and a right SIDEBAR (Trending → …). Below 1024px
   the .home-main / .home-side wrappers flatten via display:contents and the
   sections stack in one flow, re-sequenced with `order` so Trending weaves
   between Search and AI (matching the mobile concept). */
body.home-search .body-tabs { display: none !important; }
body.home-search.app-mode .topic-layout.home-grid { display: flex; flex-direction: column; gap: 0.9rem; align-items: stretch; }
body.home-search .home-cards, body.home-search .home-main, body.home-search .home-side { display: contents; }
@media (max-width: 1023.98px) {
  body.home-search .home-sections {
    display: flex; flex-direction: column; order: 2; min-width: 0;
    background: #fff; box-shadow: 0 0 0 100vmax #fff; clip-path: inset(0 -100vmax);
    padding: 1.6rem 0 2.6rem; margin-top: 0.6rem; margin-bottom: -1.5rem;
  }
  body.home-search .home-sections .home-side { order: 1; }
  body.home-search .home-sections .home-main { order: 2; margin-top: 3.4rem; }
}
body.home-search #home-search-hero { order: 1; }
body.home-search #home-trending    { order: 2; }
body.home-search #section-newsfeed { order: 4; }
/* Stacked mobile/tablet home: the quicklinks line rides directly under the search
   hero (same order slot — source order places it after). */
body.home-search .home-quicklinks { order: 1; }
@media (max-width: 1023.98px) {
  /* The longer trending list (14) is for the tall desktop right column; on mobile
     it sits between Search and AI Insights, so cap it to 6 to keep the scroll tight
     ("View more trending" still opens the full list). */
  body.home-search #home-trending .trend-card-grid .trend-card:nth-child(n+4) { display: none; }
}
/* Home trending is a vertical list (sidebar + mobile both read as a list). */
body.home-search #home-trending .trend-card-grid { grid-template-columns: 1fr; }
/* Denser homepage trending sidebar (ESPN-style headline rail): smaller responsive
   type, a 2-line summary cap, and tighter rows so more trends fit at once. Scoped
   to #home-trending so the Trending modal stays comfortable. */
#home-trending .trend-card-trigger { padding: 0.5rem 0.55rem; }
/* Even vertical rhythm: the meta line sits balanced between the title and the
   AI summary (equal gap above and below), not hugging the title. */
#home-trending .trend-card-main { gap: 5px; }
#home-trending .trend-card-head { gap: 0.45rem; }
#home-trending .trend-card-icon svg { width: 16px; height: 16px; }
#home-trending .trend-card-title { font-size: clamp(0.9rem, 0.82rem + 0.4vw, 1rem); line-height: 1.22; }
/* Category · timeframe — a clear structural meta line (medium-weight slate),
   distinct from the lighter AI summary beneath it so they don't blur together. */
#home-trending .trend-card-meta { font-size: clamp(0.68rem, 0.64rem + 0.2vw, 0.72rem); font-weight: 600; color: #5b6679; }
/* Show the full "why it's trending" summary — no 2-line clamp/ellipsis (#img290). */
#home-trending .trend-card-summary {
  font-size: clamp(0.72rem, 0.68rem + 0.2vw, 0.76rem); line-height: 1.4; margin-top: 0; color: #76829b;
}
#home-trending .trend-card-summary .ai-spark-mark { margin-right: 4px; vertical-align: -1px; }
/* Each major section reads as its own distinct white card (matching the mockup).
   overflow:hidden clips any internal header band to the rounded corners. */
body.home-search #home-trending,
/* Homepage News Feed has NO outer container — it reads as a clean list of story
   cards (the search hero, Trending, and promo carry the boxed look instead). */
body.home-search #section-newsfeed {
  background: transparent;
  border: none;
  border-radius: 0;
  overflow: visible;
}
/* Trending is a WHITE contained card (#img151) — same surface language as the
   News Feed cards (tinted header band + white body), so the expansion content
   (Explore Further rows, briefs) sits seamlessly on it. */
body.home-search #home-trending { background: transparent; border-color: transparent; }
body.home-search #home-trending .trending-topics {
  background: transparent !important;
  border-color: transparent !important;
}

/* Discreet search-area quicklinks: a "Popular" label row (label left, All topics
   right), the featured-topic pills beneath it, then a one-line nudge to the Prompt
   Library. Deliberately light — this is an EXTENSION of the search bar, not a
   section of its own, so it shares the bar's width and left edge. */
.home-quicklinks { display: flex; flex-direction: column; align-items: stretch; gap: 0.9rem; min-width: 0; text-align: left; }
.hq-group { display: flex; flex-direction: column; gap: 0.4rem; min-width: 0; }
.hq-label {
  font-family: var(--font-family); font-size: 0.74rem; font-weight: 700;
  letter-spacing: 0.06em; text-transform: uppercase; color: #8a98b0;
}
.hq-chips { display: flex; flex-wrap: wrap; align-items: center; gap: 7px 8px; max-width: 100%; min-width: 0; }
/* Shared CTA chip — same shape as the topic pills so "All topics" sits in the
   pill row as a peer, and the prompt-library link matches it a line below. */
.hq-cta {
  display: inline-flex; align-items: center; gap: 5px; height: 27px; box-sizing: border-box;
  padding: 0 11px; border-radius: 999px; border: 1px solid #dbe4f5; background: transparent;
  font-family: var(--font-family); font-size: 0.775rem; font-weight: 650; color: #3d5da8;
  white-space: nowrap; cursor: pointer; text-decoration: none;
  transition: background .12s, border-color .12s, color .12s;
}
.hq-cta svg { flex: none; transition: transform .14s ease; }
@media (hover: hover) {
  .hq-cta:hover { background: #eef3fc; border-color: #b9cbeb; color: #1d4ed8; text-decoration: none; }
  .hq-cta:hover svg { transform: translateX(2px); }
}


/* Text-only, low-contrast pills — a quiet shortcut rail under the search bar,
   not a row of badges competing with the hero. */
.hq-chip {
  display: inline-flex; align-items: center; max-width: 100%; height: 27px; box-sizing: border-box;
  padding: 0 11px; border-radius: 999px; border: 1px solid #e5e9f1; background: transparent;
  font-family: var(--font-family); font-size: 0.775rem; font-weight: 550; color: #5d6c85;
  text-decoration: none; cursor: pointer; white-space: nowrap;
  transition: background .12s, border-color .12s, color .12s;
}
.hq-chip span { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
@media (hover: hover) {
  .hq-chip:hover { background: #fff; border-color: #c8d5ec; color: #1d4ed8; text-decoration: none; }
}
@media (max-width: 560px) {
  .home-quicklinks { gap: 0.7rem; }
  .hq-chips { gap: 6px; }
  .hq-chip, .hq-cta { font-size: 0.74rem; height: 26px; padding: 0 10px; }
  .hq-label { font-size: 0.68rem; }
}
@media (min-width: 1024px) {
  /* Two rows: the three cards span the FULL width across the top, then News Feed
     (left) + Trending (right) below — so Trending starts at the News Feed row
     instead of climbing up beside the cards. */
  body.home-search.app-mode .topic-layout.home-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: "cards" "sections";
    align-items: start;
    column-gap: 1.5rem;
    /* Gap between the search zone and the News/Trending band. The quicklinks are
       light, so this doesn't need the old promo-card gap — but it does need enough
       air that the grey hero clearly ends before the white band starts. */
    row-gap: 2.1rem;
  }
  /* News + Trending live on a FULL-BLEED WHITE band (#img236/237) — the intro
     zone above keeps the faint grey; the fold to white happens here. */
  body.home-search .home-sections {
    grid-area: sections;
    display: grid; grid-template-columns: minmax(0, 1fr) 358px; column-gap: 1.5rem;
    align-items: start; min-width: 0;
    background: #fff; box-shadow: 0 0 0 100vmax #fff; clip-path: inset(0 -100vmax);
    padding: 1.7rem 0 3rem;
    margin-bottom: -3rem;
  }
  body.home-search .home-main { display: flex; flex-direction: column; gap: 1.5rem; min-width: 0; }
  /* Trending rides its own soft panel so the two columns read as distinct surfaces
     against the white News band. Desktop 2-col ONLY — below 1024px the column
     flattens into the stacked flow, where a grey block would look arbitrary. */
  body.home-search .home-side {
    display: flex; flex-direction: column; gap: 1.5rem; min-width: 0;
    background: #f6f8fb; border: 1px solid #e8edf5; border-radius: 16px;
    padding: 0.5rem 1rem 0.35rem;
  }
  /* Hairlines need a touch more contrast against the tint than they do on white. */
  body.home-search .home-side #home-trending .trending-topics-head { border-bottom-color: #dde4ef !important; }
  body.home-search .home-side #home-trending .trend-card:not(:last-child)::after { background: #e2e8f2; }
  /* Search is THE hero (#img231): full-width zone, faint knowledge icons in the
     background, the discreet quicklinks line directly beneath. */
  body.home-search .home-cards {
    grid-area: cards;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas: "search" "strip";
    gap: 0.85rem;
    align-items: start;
    min-width: 0;
  }
  body.home-search #home-search-hero { grid-area: search; }
  /* Share the search bar's exact width and left edge (the bar is a 640px column
     centred in the hero) so the quicklinks read as part of the search area. */
  body.home-search .home-quicklinks { grid-area: strip; max-width: 640px; width: 100%; margin: 0 auto; }
  /* Reset the mobile-stacking `order` so everything lays out in source order. */
  body.home-search #home-search-hero,
  body.home-search .home-quicklinks,
  body.home-search .home-sections,
  body.home-search #section-newsfeed,
  body.home-search #home-trending { order: 0; }
  /* LEFT-ALIGNED hero (#img154): big display title, tagline, bar — no card box.
     The art column carries the visual weight on the right. */
  /* CENTERED hero (#img363): title, tagline and the search bar are centered as a
     single column over the cards below. */
  body.home-search .home-search-hero { display: block; padding: 0 0 0.35rem; border-radius: 0; text-align: center; width: 100%; max-width: none; margin: 0; justify-self: stretch; }
  body.home-search .home-search-hero .search-panel { max-width: none; margin: 0; }
  body.home-search .home-search-hero .search-panel-hero-inner { text-align: center; padding: 0 0 1.05rem; }
  body.home-search .home-search-hero .search-panel-title {
    white-space: normal; text-align: center;
    font-size: clamp(1.85rem, 1.35rem + 1vw, 2.35rem); font-weight: 780;
    letter-spacing: -0.032em; line-height: 1.1; color: #16233d; margin: 0 0 0.65rem;
  }
  body.home-search .home-search-hero .search-panel-tagline { text-align: center; margin: 0 auto 0.3rem; font-size: 1.14rem; color: #4a5a75; }
  body.home-search .home-search-hero .search-panel-input { height: 48px; font-size: 0.98rem; }
  body.home-search .home-search-hero .search-panel-barrow { max-width: 640px; margin-left: auto; margin-right: auto; padding-left: 0; padding-right: 0; }
  /* Topic/trend chips dropped from the desktop search card. */
  body.home-search .home-search-hero .search-panel-starters { display: none; }
}
/* Stacked (<1024): centered hero, then the mobile art band, then the mini-cards.
   Bigger title/tagline through this range (#img194/195); the art band runs (near)
   full width with its lines bleeding past the edges, tucked closer to the search. */
@media (max-width: 1023.98px) {
  body.home-search .home-search-hero .search-panel-title { font-size: clamp(1.95rem, 1.2rem + 3.6vw, 2.5rem); font-weight: 760; color: #16233d; letter-spacing: -0.028em; }
  body.home-search .home-search-hero .search-panel-tagline { font-size: 1rem; }
}
/* Cards size to content + the page scrolls. */
body.home-search .layout-section,
body.home-search .shortcuts-sidebar,
body.home-search .newsfeed-card { height: auto; overflow: visible; }
body.home-search .topic-layout .shortcuts-scroll-wrap,
body.home-search .topic-layout .newsfeed-scroll-wrap {
  flex: none; height: auto; max-height: none; overflow: visible;
}
/* News Feed never overflows its column — global insurance against long
   titles/URLs (applies on home + topic pages). */
#section-newsfeed, .newsfeed-card, .newsfeed-scroll-wrap, .news-list, .news-card, .news-card-link { min-width: 0; max-width: 100%; }
.news-card-title, .news-card-desc { overflow-wrap: anywhere; }

body.home-search #topic-layout { margin-top: 0.4rem; }

/* Stacked layout (<1024px): the .home-grid flex column + gap spaces the cards,
   so no per-section margins. Keep the Intelligence panel's tightened padding. */
@media (max-width: 1023.98px) {
  body.home-search.app-mode .topic-layout > .layout-section { flex: none; overflow: visible; min-height: 0; }
  body.home-search #section-aii-home .shortcuts-scroll-wrap { padding-top: 0.5rem; padding-bottom: 0; }
  body.home-search .home-search-hero .search-panel { max-width: none; margin-left: auto; margin-right: auto; }
  body.home-search .home-search-hero .search-panel-title { font-size: clamp(1.2rem, 0.95rem + 1vw, 1.45rem); }
}
/* Stacked mid-range (641–1023 — nav icons still on the title row): the search
   card KEEPS the centred desktop cap + the desktop title/tagline/bar formatting,
   so resizing below 1024 doesn't snap it to an edge-to-edge bar (#img580). */
@media (min-width: 641px) and (max-width: 1023.98px) {
  body.home-search .home-search-hero {
    width: min(100%, 820px); max-width: none; margin: 0 auto;
    padding: 2rem 1.6rem; border-radius: 16px; text-align: center;
  }
  body.home-search .home-search-hero .search-panel-tagline { margin: 0 auto 1.2rem; font-size: 0.95rem; }
  /* Same tagline→bar gap as desktop across the WHOLE mid-range — the base 1rem
     hero-inner padding-bottom only tightened to 0.2rem at ≥700, leaving 641–699
     with a visibly airier gap (#img584). */
  body.home-search .home-search-hero .search-panel-hero-inner { padding-bottom: 0.2rem; }
  body.home-search .home-search-hero .search-panel-input { height: 48px; font-size: 0.98rem; }
}
/* Only once the main nav breaks to two rows (≤640) does the search card go
   FULL-WIDTH, matching the Trending/News cards below it (#233/#234/#235). The
   hero is a grid item (its parent is display:contents), so force it to stretch —
   auto side-margins would shrink it to its content. */
@media (max-width: 640px) {
  body.home-search .home-search-hero { width: auto !important; max-width: none !important; margin: 0 !important; justify-self: stretch !important; }
}

/* === Phase 14: search panel refinements ============================== */
/* Actions group (Copy link + single close X) to the RIGHT of the bar. */
.search-panel-barrow { display: flex; align-items: center; gap: 0.5rem; }
.search-panel-form { flex: 1 1 auto; min-width: 0; }
/* X (close) sits first, Copy link second — row-reverse keeps the DOM order
   (copy, close) but renders close → copy left-to-right. */
.search-panel-actions { flex: 0 0 auto; display: flex; flex-direction: row-reverse; align-items: center; gap: 0.4rem; }
.search-panel-close {
  flex: 0 0 auto; width: 36px; height: 36px; box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center;
  background: #f1f3f7; border: 1px solid #e7eaf0; border-radius: 9px;
  color: var(--color-text-muted); cursor: pointer; transition: background 0.14s, color 0.14s;
}
@media (hover: hover) { .search-panel-close:hover { background: #e8ecf2; color: var(--color-text); } }
.search-panel-close svg { width: 16px; height: 16px; display: block; }
.search-panel-copy { white-space: nowrap; }
/* Copy link only once a term is searched. */
.search-panel[data-state="collapsed"] .search-panel-copy { display: none; }
/* Homepage hero: no X until something is searched. */
.search-panel--inline[data-state="collapsed"] .search-panel-close { display: none; }
/* Modal empty hero: keep the close X inline at the right of the bar, and
   give the search bar breathing room beneath it (Image #17). */
.search-panel--modal[data-state="collapsed"] .search-panel-barrow { margin-bottom: 0; border-bottom: none; }

/* Search results header: rename is in JS ("Search Intelligence"); here make
   it smaller, give room above (below the bar) and tighten it to the
   accordions. */
/* "Search Intelligence" header: ~14px of breathing room above it (from the
   bar) and a matching ~14px below the divider to the accordions, so it's
   not cramped against the bar while floating far from the cards. */
.search-panel-results .shortcuts-sidebar { margin-top: 1.15rem; }
.search-panel-results .sidebar-card-header { padding-bottom: 0.45rem; }
/* Always a navy title — override the mobile .topic-intelligence-panel rule
   that turns it into an uppercase slate eyebrow (the search hero wants the
   same readable title as desktop, not a section eyebrow). */
.search-panel-results .topic-intelligence-panel .sidebar-card-title,
.search-panel-results .sidebar-card-title {
  font-family: var(--font-display);
  font-size: 1.2rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  text-transform: none;
  color: #1c3a6b;
}
/* Kill the stacked vertical slack below the header (mobile header margin +
   scroll-wrap top padding) so the accordions sit a tidy ~14px below it. */
.search-panel-results .topic-intelligence-panel .sidebar-card-header { margin-bottom: 0; }
/* The home grid's `topic-layout:not(.is-custom) .shortcuts-scroll-wrap`
   rule adds ~1.4rem top padding here; out-specify it (and cover the modal
   with the plain selector) so the accordions sit ~14px below the header. */
.search-panel-results .shortcuts-scroll-wrap,
body.home-search.app-mode .topic-layout .search-panel-results .shortcuts-scroll-wrap { padding-top: 0; padding-bottom: 0; }
/* In the search modal the WHOLE results area scrolls (.search-panel-results) —
   the AI Intelligence panel must NOT carry its own inner scrollbar (#87). */
.search-panel-results .shortcuts-scroll-wrap { overflow: visible; flex: none; max-height: none; -webkit-mask-image: none; mask-image: none; }
.search-panel-results .topic-intelligence-panel { overflow: visible; }
.search-panel-results .ti-accordions { padding-top: 0.85rem; }
/* Equal-height lens cards (#87): center content within a consistent min-height
   so a 1-line and a 2-line description produce the same card size. */
.search-panel-results .ti-accordion:not([open]) .ti-accordion-summary { min-height: 4.6rem; align-content: center; }
/* Keep the live search-term sublabel visible in the results at every width
   (the generic .ti-topic-sublabel rule hides it below 900px for topic pages). */
.search-panel-results .ti-topic-sublabel { display: block; }
/* "Search Intelligence" header is a row: heading on the left, Copy link
   pinned top-right (relocated here from the search bar). */
.search-panel-results .sidebar-card-header { align-items: flex-start; justify-content: space-between; gap: 0.75rem; }
.search-panel-results .sidebar-card-heading { flex: 1 1 auto; min-width: 0; }
.search-panel-results .search-panel-copy { flex: 0 0 auto; align-self: flex-start; }

/* Accordions open IN PLACE within their own grid column (no full-width
   span) — the row simply grows to fit the open one while its neighbour
   stays top-aligned. */

/* Mobile: the tab band goes full-bleed (edge to edge) again. */
@media (max-width: 899.98px) {
  body.home-search.app-mode .topic-layout { padding-left: 1.25rem; padding-right: 1.25rem; }
  body.home-search .body-tabs {
    margin: 0 -1rem; padding: 0.6rem 1rem; background: #eef1f6;
  }
  /* TI / sections flow their full content on mobile (no clipped accordions). */
  body.home-search.app-mode .topic-layout > .layout-section .shortcuts-sidebar { height: auto; }
  /* The search hero's "Search Intelligence" block is inline results
     labeling — NOT a tab-labeled panel — so keep its header visible even
     though the generic mobile rule hides section headers. */
  body.home-search.app-mode .topic-layout .search-panel-results .shortcuts-sidebar .sidebar-card-header { display: flex; }
  /* Gap between the search section and the Trending card. Expanded
     (results showing) stays tight; collapsed (empty search bar) gets a
     little more breathing room below the bar. */
  /* Seat the tab band flush under the subnav — drop the ~10px of white
     space above it (the topic-layout's 0.4rem margin + content's 0.25rem
     padding slack). */
  body.home-search.app-mode.sticky-always.has-subnav #content { padding-top: calc(var(--nav-h) + var(--subnav-height, 80px) + 0.7rem); }
  body.home-search #topic-layout { margin-top: 0; }
}

/* Hide the native type="search" clear button — we have one explicit X. */
.search-panel-input::-webkit-search-cancel-button,
.search-panel-input::-webkit-search-decoration { -webkit-appearance: none; appearance: none; display: none; }

/* === Trending section (homepage + Trending modal) ==================== */
.home-trending { margin: 1.6rem 0 0; padding: 0; }
/* Trending gap is state-aware — roomier when the search is collapsed, tighter
   once results are showing below the bar. MOBILE ONLY: on desktop the
   single-column grid's row-gap alone spaces Search → Trending (this adjacency
   margin would stack on top of the gap and push Trending too far down). */
@media (max-width: 899.98px) {
  /* Even rhythm (#8/#9): the .home-grid gap alone spaces the cards — drop the
     extra adjacency margin that made Search↔Trending too far while Trending sat
     too tight to AI/News. One consistent gap for the whole stack. */
  body.home-search.app-mode .topic-layout.home-grid { gap: 1.6rem; }
  body.home-search #home-search-hero + #home-trending { margin-top: 0; }
  body.home-search #home-trending { margin-top: 0; }
}
/* Desktop home now shows the "Featured | …" subnav (fixed under the main nav),
   so reserve its height + a gap so the search card clears it (was: subnav hidden,
   main-nav carried the topics). Zero Trending's base margin so its top aligns
   with the Search card across the two columns. */
@media (min-width: 1024px) {
  body.home-search.app-mode.sticky-always.has-subnav #content { padding-top: calc(var(--nav-h) + var(--subnav-height, 66px) + 1rem); }
  body.home-search #home-trending { margin-top: 0; }
}
/* On the homepage the whole section sits in a soft card to set it apart. */
/* Plain section (no gray card) so Trending reads in the same continuous
   flow as Intelligence / News Feed below it. */
.home-trending .trending-topics { background: transparent; border: none; border-radius: 0; padding: 0; }
/* Header — a clear "Trending" title with the teal trend icon; the source +
   updated meta sit just below it as a subtitle. */
/* Header: one line on desktop — title left, descriptive sentence + a
   "Last Updated" pill pushed to the right; stacks on mobile. */
/* Title + "Updated" pill on the first line; the descriptive subtext sits
   below as a subtitle (matches News Feed / Intelligence section heads). */
.trending-topics-head { margin-bottom: 0.9rem; padding-bottom: 0.7rem; border-bottom: 1px solid #d6dae2; }
.trending-topics-titlerow { display: flex; align-items: center; gap: 0.65rem; flex-wrap: wrap; }
/* Icon tile — matches the AI Intelligence header lockup. */
.trending-topics-logo { display: inline-flex; width: 26px; height: 26px; flex: none; align-items: center; justify-content: center; border-radius: 8px; background: var(--color-primary); color: #fff; }
.trending-topics-logo svg { width: 14px; height: 14px; }
.trending-topics-title { margin: 0; font-family: var(--font-display); font-size: 1.16rem; font-weight: 700; letter-spacing: -0.015em; line-height: 1.5; color: var(--color-text); }
.trending-topics-updated { margin-left: auto; align-self: center; font-size: 0.62rem; font-weight: 600; letter-spacing: 0.01em; color: #6b7689; background: #eef1f6; padding: 0.24rem 0.55rem; border-radius: 6px; white-space: nowrap; line-height: 1; }
.trending-topics-sub { margin: 7px 0 0; font-size: 0.8rem; line-height: 1.45; color: var(--color-text-muted); }
.trending-topics-src { color: #5f6b85; text-decoration: none; }
@media (hover: hover) { .trending-topics-src:hover { color: #1f8f6b; text-decoration: underline; } }

/* === Card-based sections (desktop, #106): Trending + News Feed get the same
   faint primary-tinted header band + rounded card as AI Intelligence. The
   News Feed search + sort move INTO the header, aligned with the title and
   wrapping below it when the row gets tight. Scoped to ≥900px (the wide,
   non-tab view) so the mobile tab layout is untouched. ====================== */
@media (min-width: 900px) {
  /* Trending (homepage left column) */
  body.home-search #home-trending .trending-topics {
    border: 1px solid var(--color-surface-border); border-radius: 16px;
    background: #fff; overflow: hidden; padding: 0;
  }
  /* Match the AI Intelligence header metrics exactly (padding + gap) so the two
     side-by-side cards' header bands are the same height. */
  /* Inline head: title left, descriptive sentence to its right, "Updated" pill
     pushed to the far right (#220-222). display:contents on the titlerow flattens
     logo + title + pill into the head's flex so order can interleave the sub. */
  body.home-search #home-trending .trending-topics-head {
    margin: 0; padding: 15px 18px; display: flex; flex-direction: column; align-items: flex-start; gap: 8px;
    border-bottom: 1px solid var(--color-surface-border);
    background: color-mix(in srgb, var(--color-primary) 3%, #fff);
  }
  body.home-search #home-trending .trending-topics-titlerow { display: flex; align-items: center; gap: 12px; width: 100%; }
  body.home-search #home-trending .trending-topics-sub { margin: 0; }
  body.home-search #home-trending .trending-topics-updated { margin-left: auto; }
  body.home-search #home-trending .trend-card-grid { padding: 4px 12px 4px; }
  body.home-search #home-trending .trend-viewmore-row { margin-top: 2px; padding: 0 14px 20px; }

  /* News Feed (homepage + topic pages). Higher specificity (.newsfeed-card
     ancestor) so these win over the base #section-newsfeed .newsfeed-head. */
  #section-newsfeed .newsfeed-card {
    border: 1px solid var(--color-surface-border); border-radius: 16px;
    background: #fff; overflow: visible;
  }
  /* News Feed needs no subtext — put the title left and the search + sort to its
     RIGHT on one row (#220), instead of stacking the controls below. */
  #section-newsfeed .newsfeed-card .newsfeed-head {
    display: flex; flex-direction: row; align-items: flex-start; justify-content: space-between;
    gap: 16px; margin: 0; padding: 15px 18px;
    border-bottom: 1px solid var(--color-surface-border);
    background: color-mix(in srgb, var(--color-primary) 3%, #fff);
    border-radius: 16px 16px 0 0;
  }
  /* Search + sort ride the title row (#78), not centred across the two-line
     text block. The filters block self-aligns to the top of the header. */
  /* Title+icon on top, "Latest stories and developments." stacked on its OWN
     line below (#76); search/sort sit to the right, on the title row. The text
     block must NOT shrink — otherwise the subtext wraps/ellipsizes. It sizes to
     its widest line (the subtext) and the filters take the remaining width. */
  #section-newsfeed .newsfeed-card .newsfeed-headtext { display: flex; flex-direction: column; align-items: flex-start; gap: 5px; flex: 0 0 auto; }
  #section-newsfeed .newsfeed-card .section-card-sub { display: block; flex: none; white-space: nowrap; }
  /* Reset the legacy full-bleed title chrome (white bg + min-height + bottom
     rule) that caused the centered white box; clean inline lockup instead. */
  #section-newsfeed .newsfeed-card .newsfeed-title {
    display: inline-flex; flex-direction: row; align-items: center; justify-content: flex-start; align-self: flex-start; gap: 0.7rem;
    background: transparent; min-height: 0; border-bottom: none; padding: 0; margin: 0;
    /* Exactly match the AI Insights header (.aii-brand): 1.16rem / 600. */
    font-size: 1.16rem; font-weight: 600; letter-spacing: -0.015em; color: var(--color-text);
  }
  /* Filters sit naked in the header band (just the search field + sort) — no
     wrapping box (the box-in-box looked heavy). To the right of the title. */
  /* Fixed, modest width — flex-grow 0 so the search never balloons on wide
     viewports (#103); shrinkable so it never pushes the sort past the edge. */
  #section-newsfeed .newsfeed-card .nf-search-wrap { flex: 0 1 240px; width: auto; max-width: 240px; }
  /* Stories run the full card width — drop the scroll-wrap's horizontal padding
     so each story's clickable link + hover fill span edge-to-edge (no dead,
     un-clickable gutter, #244). The text inset moves onto the link/foot so titles
     still align with the header. Empty/loading states keep an inset of their own. */
  /* No top gap above the list — the first story's breathing room lives INSIDE its
     card so the hover/active fill covers it (and isn't a dead white strip). */
  #section-newsfeed .newsfeed-card .newsfeed-scroll-wrap { padding: 0 0 6px; }
  /* More room under the tab bar for the first story (#264). */
  body.app-mode:not(.home-search) .topic-layout:not(.is-custom) #section-newsfeed .news-list .news-card:first-child .news-card-link { padding-top: 1.15rem; }
  #section-newsfeed .newsfeed-card .newsfeed-foot { padding: 0 18px 14px; }
  #section-newsfeed .newsfeed-card .news-card-link,
  #section-newsfeed .newsfeed-card .news-card-foot,
  #section-newsfeed .newsfeed-card .news-empty,
  #section-newsfeed .newsfeed-card .news-loading,
  #section-newsfeed .newsfeed-card .news-error,
  #section-newsfeed .newsfeed-card .newsfeed-placeholder { padding-left: 18px; padding-right: 18px; }
}
/* News Feed icon tile — matches the AI Intelligence / Trending header lockups. */
