@media (hover: hover) { body.home-search #home-trending .trend-viewmore:hover { background: none; border: none; color: #1d4ed8; text-decoration: underline; gap: 9px; } }
/* Stacked-home extras: hide the AI legend, tighter grid top. (Row content — navy
   title + terse summary + chevron — is now the SAME at every width via the
   What's-Trending rules earlier in this file.) */
@media (max-width: 1023.98px) {
  body.home-search #home-trending .trend-legend-row { padding: 4px 0 0 !important; }
  body.home-search #home-trending .trend-card:first-child .trend-card-trigger { padding-top: 12px !important; }
  body.home-search #home-trending .trend-card-grid { padding-top: 2px !important; }
}
/* Row polish at EVERY width: full-width head (right-aligned marker), title clear
   of the marker, weight 650, flat row hover matching the divider inset (#img146). */
body.home-search #home-trending .trend-card-main,
body.home-search #home-trending .trend-card-head { width: 100%; }
body.home-search #home-trending .trend-card-acc { display: inline-flex; margin-right: 8px; }
body.home-search #home-trending .trend-card-title { padding-right: 10px; font-weight: 650 !important; }
body.home-search #home-trending .trend-card:hover::before { content: none !important; }
@media (hover: hover) { body.home-search #home-trending .trend-card:not(.is-expanded):hover { background: #f5f7fa; } }
/* First card's hover fill reaches the header rule above it — the grid's small top
   pad was leaving a sliver of white between the tint and the divider (#img320/321). */
@media (hover: hover) { body.home-search #home-trending .trend-card:first-child:not(.is-expanded):hover { box-shadow: 0 -3px 0 0 #f5f7fa; } }
/* In-between stacked width (641–1023.98): SIX trends in TWO columns instead of a
   3-row list (#img127). An expanded brief spans both columns. First-row cells both
   drop the tighter first-child top padding for an even grid. */
@media (min-width: 641px) and (max-width: 1023.98px) {
  body.home-search #home-trending .trend-card-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); column-gap: 0; }
  body.home-search #home-trending .trend-card-grid .trend-card:nth-child(-n+6) { display: block; }
  body.home-search #home-trending .trend-card-grid .trend-card:nth-child(n+7) { display: none; }
  body.home-search #home-trending .trend-card:first-child .trend-card-trigger { padding-top: 14px !important; }
  body.home-search #home-trending .trend-card.is-expanded { grid-column: 1 / -1; }
}
/* News Feed section header on the homepage gets a matching icon chip (like the
   Trending logo) — desktop + mobile. Hidden everywhere else (topic pages keep
   their own plain header) (#img527). */
.newsfeed-logo { display: none; }
body.home-search #section-newsfeed .newsfeed-title { gap: 0.6rem; }
body.home-search #section-newsfeed .newsfeed-logo { display: inline-flex; width: 26px; height: 26px; flex: none; align-items: center; justify-content: center; border-radius: 8px; background: var(--color-primary); color: #fff; }
