@media (min-width: 1024px) {
  body.home-search #section-newsfeed .newsfeed-title, body.home-search #section-newsfeed .newsfeed-title-main,
  body.home-search #home-trending .trending-topics-title { font-size: 1.34rem !important; }
  body.home-search #section-newsfeed .newsfeed-logo, body.home-search #home-trending .trending-topics-logo { width: 30px !important; height: 30px !important; border-radius: 9px !important; }
  body.home-search #home-trending .trending-topics-logo svg { width: 16px !important; height: 16px !important; }
  /* News Feed glyph rendered a touch larger + heavier so the document icon
     matches the Trending arrow's visual size in the 30px chip (#img6/7). */
  body.home-search #section-newsfeed .newsfeed-logo svg { width: 19px !important; height: 19px !important; stroke-width: 2.4 !important; }
}
/* Desktop Trending header font matches the News Feed header exactly (#img528/529). */
