.aii-nav-dd-trending .trend-card-head { display: block !important; width: 100%; padding-right: 26px; }
body.home-search #home-trending .trend-card-title,
.aii-nav-dd-trending .trend-card-title { display: block; padding-right: 0 !important; }
body.home-search #home-trending .trend-card-summary,
.aii-nav-dd-trending .trend-card-summary { padding-right: 26px; }
/* One quiet chevron, vertically centred on the row's right edge. */
body.home-search #home-trending .trend-card-acc,
.aii-nav-dd-trending .trend-card-acc {
  position: absolute; top: 50%; right: 0; transform: translateY(-50%);
