  color: #c2ccdc; transition: color .14s ease;
}
body.home-search #home-trending .trend-card-acc svg,
.aii-nav-dd-trending .trend-card-acc svg { width: 16px; height: 16px; }
@media (hover: hover) {
  body.home-search #home-trending .trend-card-trigger:hover .trend-card-acc,
  .aii-nav-dd-trending .trend-card-trigger:hover .trend-card-acc { color: #64748b; }
}

/* ── Expanded trend: one close control (the button at the end), nothing else ── */
