.aii-nav-dd-trending .trend-card.is-expanded .trend-card-meta { display: none !important; }
body.home-search #home-trending .trend-card.is-expanded .trend-card-acc,
.aii-nav-dd-trending .trend-card.is-expanded .trend-card-acc { display: none !important; }
body.home-search #home-trending .trend-card.is-expanded .trend-card-actions,
.aii-nav-dd-trending .trend-card.is-expanded .trend-card-actions { display: none !important; }
body.home-search #home-trending .trend-card.is-expanded .trend-card-chev,
.aii-nav-dd-trending .trend-card.is-expanded .trend-card-chev { display: none !important; }

/* AI provenance inside the brief reads exactly like the line under the section
