.te-drawer > .te-drawer-sum { padding: 10px 2px; font-size: 0.82rem; font-weight: 600; }
.te-drawer-ic { display: none; }
.te-drawer-chev { width: 15px; height: 15px; }
.te-drawer-chev svg { width: 15px; height: 15px; }
/* Explore Further inside a drawer uses the same clipped accordion list as the
   topic page's Web Resources, at drawer scale. */
.te-drawer-body .xf-list {
