body.home-search #home-trending .trend-card.is-expanded .trend-card-acc,
.aii-nav-dd-trending .trend-card.is-expanded .trend-card-acc {
  display: inline-flex !important; position: absolute; top: -2px; right: 0; transform: none;
  width: 28px; height: 28px; align-items: center; justify-content: center;
