.aii-nav-dd-trending .trend-card-meta { font-size: 0.72rem; font-weight: 600; color: #5b6679; }
.aii-nav-dd-trending .trend-card-summary { color: #55617a; }
.aii-nav-dd-trending .trend-card.is-expanded {
